// ---------- compact answered bitset ----------
const bitCache=new WeakMap();
function bitBytes(stats){ if(bitCache.has(stats))return bitCache.get(stats); const n=Math.ceil((MANIFEST?.storageQuestions||MANIFEST?.totalQuestions||40000)/8), b=new Uint8Array(n); if(stats.answeredBits){try{const raw=atob(stats.answeredBits);for(let i=0;i<raw.length&&i<n;i++)b[i]=raw.charCodeAt(i)}catch{}} bitCache.set(stats,b); return b }
