function me(){return state.users.find(u=>u.id===state.currentUser)}
function targetStudent(){const m=me();if(m?.role==='student')return m;return state.users.find(u=>u.role==='student')||m}
function stats(uid=targetStudent()?.id){if(!state.stats[uid])state.stats[uid]=blankStats();return state.stats[uid]}
function gradeName(g){return Number(g)<=9?`${g}º ano`:`${Number(g)-9}º ano EM`}
function pct(x){return Math.max(0,Math.min(100,Math.round(Number(x)||0)))}
function recalc(s){s.knowledge=s.questions?Math.round(s.masteredCorrect/s.questions*100):0;const n=s.cdf.C+s.cdf.D+s.cdf.F;s.confidence=n?Math.round((s.cdf.C*100+s.cdf.D*60+s.cdf.F*20)/n):0;const avg=s.questions?s.timeMs/s.questions:0;s.speed=s.questions?Math.max(0,Math.min(100,Math.round(100-(avg/1000-35)*.7))):0;s.mastery=Math.round(s.knowledge*.55+s.confidence*.25+s.speed*.20)}
