// ---------- AEDS 9.0: semantic anti-repetition + micro-skill mastery ----------
function structuralPrompt(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\b\d+[ºo]?\s*ano(?:\s+do\s+ensino\s+medio)?\b/g,' ').replace(/[−–—]/g,'-').replace(/×/g,'*').replace(/÷/g,'/').replace(/\d+(?:[.,]\d+)?/g,' # ').replace(/([+\-*/=<>≤≥|()^²³])/g,' $1 ').replace(/[^a-z#²³+\-*/=<>≤≥|()^% ]+/g,' ').replace(/\s+/g,' ').trim()}
function similarityTokens(v){return structuralPrompt(v).split(' ').filter(x=>x.length>2||x==='#'||/^[a-z]$/.test(x)||/^[+\-*/=<>≤≥|()^²³%]+$/.test(x))}
function promptPattern(q){return q?.patternFamily||structuralPrompt(q?.prompt)}
function promptSimilarity(a,b){const A=new Set(similarityTokens(a)),B=new Set(similarityTokens(b));if(!A.size||!B.size)return 0;let inter=0;for(const x of A)if(B.has(x))inter++;return inter/(A.size+B.size-inter)}
function hydrateAntiRepeat(s){if(!s||s.antiRepeatV823)return;const roots=new Set([...(s.answeredRoots||[]),...(s.recentRoots||[])]),patterns=new Set([...(s.answeredPatterns||[]),...(s.recentPatterns||[])]);for(const q of BANK){if(q.n!=null&&q.n>=0&&answeredHas(s,q.n)){if(q.rootFamily||q.family)roots.add(q.rootFamily||q.family);const p=promptPattern(q);if(p)patterns.add(p)}}for(const id of s.answeredCustom||[]){const q=qById(id);if(q){if(q.rootFamily||q.family)roots.add(q.rootFamily||q.family);const p=promptPattern(q);if(p)patterns.add(p)}}for(const h of s.history||[]){const q=qById(h.qid);if(q){if(q.rootFamily||q.family)roots.add(q.rootFamily||q.family);const p=promptPattern(q);if(p)patterns.add(p)}}s.answeredRoots=[...roots];s.answeredPatterns=[...patterns];s.antiRepeatV823=true}
function isQuestionFresh(q,s=stats()){if(!q)return false;if(q.n!=null&&q.n>=0){if(answeredHas(s,q.n))return false}else if((s.answeredCustom||[]).includes(q.id))return false;const root=q.rootFamily||q.family,pat=promptPattern(q);if(root&&(s.answeredRoots||[]).includes(root))return false;if(pat&&(s.answeredPatterns||[]).includes(pat))return false;for(const old of (s.recentPrompts||[]).slice(-24))if(promptSimilarity(q.prompt,old)>=.78)return false;return true}
function markQuestionSeen(s,q){const root=q.rootFamily||q.family,pat=promptPattern(q);if(root&&!s.answeredRoots.includes(root))s.answeredRoots.push(root);if(pat&&!s.answeredPatterns.includes(pat))s.answeredPatterns.push(pat);if(root){s.recentRoots.push(root);s.recentRoots=s.recentRoots.slice(-120)}if(pat){s.recentPatterns.push(pat);s.recentPatterns=s.recentPatterns.slice(-120)}s.recentPrompts.push(q.prompt||'');s.recentPrompts=s.recentPrompts.slice(-40);if(q.correctText){s.recentAnswers.push(q.correctText);s.recentAnswers=s.recentAnswers.slice(-40)}if(Number.isInteger(q.correctIndex)){s.recentCorrectIndexes.push(q.correctIndex);s.recentCorrectIndexes=s.recentCorrectIndexes.slice(-12)}}
function keySkill(q){return `${q.subject}|${q.grade}|${q.area}|${q.skill||q.area}`}
function ensureSkillStat(s,q){const k=keySkill(q);return s.skill[k]||(s.skill[k]=AEDS_ENGINE.normalizeSkillStat({}))}
function recordSkillResult(s,q,right,cdf,elapsed){const x=ensureSkillStat(s,q);AEDS_ENGINE.updateSkill(x,{right,cdf,difficulty:q.difficulty,elapsed,now:Date.now()})}
