function autonomyRecord(subject,grade,area,uid=targetStudent()?.id){if(!uid)return {understood:false,external:false,explained:false};const key=`${subject}|${grade}|${area}`,bag=state.independence[uid]||(state.independence[uid]={});if(!bag[key])bag[key]={understood:!!state.prereqDone?.[uid]?.[key],external:false,explained:false,updatedAt:0};return bag[key]}
function topicExternalProof(subject,grade,area,uid=targetStudent()?.id){const r=autonomyRecord(subject,grade,area,uid);return !!(r.understood&&r.external&&r.explained)}
function stageForSkillKey(key,uid=targetStudent()?.id){const s=stats(uid),x=s.skill[key]||AEDS_ENGINE.normalizeSkillStat({}),[subject,grade,area]=key.split('|');return AEDS_ENGINE.stage(x,topicExternalProof(subject,grade,area,uid))}
function stageBadge(key,uid=targetStudent()?.id){const st=stageForSkillKey(key,uid);return `<span class="stage-badge stage-${st.level}" title="${esc(AEDS_ENGINE.reviewLabel(stats(uid).skill[key]))}">${st.icon} ${esc(st.label)}</span>`}
