function masteryOverviewHtml(uid=targetStudent()?.id){const s=stats(uid),rows=Object.entries(s.skill).filter(([,v])=>v?.done);const counts=[0,0,0,0,0];for(const [k] of rows)counts[stageForSkillKey(k,uid).level]++;const due=dueSkillKeys(uid).length;return `<div class="card mastery-ladder"><div class="page-head" style="margin-bottom:10px"><div><h3 style="margin:0">Escada de domínio</h3><div class="tiny muted">O objetivo é chegar à independência, não acumular tempo dentro do site.</div></div><span class="pill">${due} revisões hoje</span></div><div class="mastery-stage-grid"><div><span>🌱</span><b>${counts[1]}</b><small>Conhecendo</small></div><div><span>🧠</span><b>${counts[2]}</b><small>Entendendo</small></div><div><span>🔄</span><b>${counts[3]}</b><small>Aplicando</small></div><div><span>🏆</span><b>${counts[4]}</b><small>Independente</small></div></div></div>`}
function autonomyPanelHtml(subject,grade,area){const r=autonomyRecord(subject,grade,area),done=r.understood&&r.external&&r.explained;const step=(k,icon,title,sub)=>`<button class="autonomy-step ${r[k]?'done':''}" data-autonomy-step="${k}"><span>${r[k]?'✅':icon}</span><b>${title}</b><small>${sub}</small></button>`;return `<section class="autonomy-proof-card"><div class="page-head" style="margin-bottom:9px"><div><h3 style="margin:0">🎒 Prova de independência</h3><div class="tiny muted">Só marque o que você realmente fez. AEDS não deve substituir escola, professor, livro ou caderno.</div></div><span class="stage-badge ${done?'stage-4':'stage-2'}">${done?'🏆 Independência externa':'em construção'}</span></div><div class="autonomy-steps">${step('understood','🧠','Expliquei com minhas palavras','sem copiar a definição')}${step('external','📚','Resolvi fora da AEDS','escola, livro, folha ou outra fonte')}${step('explained','🗣️','Ensinei sem consultar','consegui justificar o porquê')}</div><div class="autonomy-foot">${done?'Ótimo. Agora use a AEDS só para revisão espaçada e problemas realmente novos.':'Não precisa correr. Independência vale mais que terminar a página.'}</div></section>`}
function addFeedback(kind,ref,detail=''){const u=targetStudent()||me();state.feedback.push({id:`FB-${Date.now()}`,at:new Date().toISOString(),userId:u?.id||'',user:u?.name||u?.username||'usuário',kind,ref,detail});state.feedback=state.feedback.slice(-1000);audit('feedback',`${kind}: ${ref}`)}
function feedbackAdminHtml(){const rows=state.feedback.slice(-80).reverse();return `<div class="card" style="margin-top:14px"><div class="page-head" style="margin-bottom:8px"><div><h3 style="margin:0">Feedback real de uso</h3><div class="tiny muted">Use isto durante testes com alunos para descobrir telas, aulas e questões confusas.</div></div><span class="pill">${state.feedback.length}</span></div>${rows.length?`<div class="list">${rows.map(x=>`<div class="item"><b>${esc(x.kind)}</b> · ${esc(x.user)}<div class="small">${esc(x.ref)}</div><div class="tiny muted">${new Date(x.at).toLocaleString('pt-BR')}${x.detail?` · ${esc(x.detail)}`:''}</div></div>`).join('')}</div>`:'<div class="notice">Nenhum feedback registrado ainda.</div>'}</div>`}
function generalSkillDiagnosisHtml(){const uid=targetStudent()?.id,s=stats(uid),rows=Object.entries(s.skill).filter(([k,v])=>v.done&&!k.startsWith('Matemática|')&&!k.startsWith('Português|')).map(([k,v])=>{const [subject,g,area,...sk]=k.split('|'),st=stageForSkillKey(k,uid);return {k,subject,g:Number(g),area,skill:sk.join('|'),done:v.done,errors:v.errors||0,stage:st}});if(!rows.length)return'';const weak=[...rows].sort((a,b)=>a.stage.level-b.stage.level||a.stage.accuracy-b.stage.accuracy||b.errors-a.errors).slice(0,8);return `<div class="card" style="margin-top:14px"><h3>Diagnóstico das outras matérias</h3><p class="muted small">A AEDS também acompanha micro-habilidades fora de Matemática e Português quando o banco fornece essa identificação.</p><div class="list">${weak.map(x=>`<div class="item"><div style="display:flex;justify-content:space-between;gap:8px"><div><b>${esc(x.subject)} · ${esc(x.skill||x.area)}</b><div class="tiny muted">${gradeName(x.g)} · ${esc(x.area)} · ${x.done} tentativas</div></div>${stageBadge(x.k,uid)}</div></div>`).join('')}</div></div>`}
function smartEligiblePool(){const u=targetStudent(),s=stats(u?.id),subs=new Set(availableSubjects(u)),grades=new Set(u?.unlockedGrades||[u?.grade]);return candidateBank().filter(q=>q.active!==false&&q.questionType==='multiple_choice'&&subs.has(q.subject)&&grades.has(Number(q.grade))&&isQuestionFresh(q,s))}
function smartPlan(mode='study',limit=7){const s=stats(),pool=smartEligiblePool(),chosen=[],roots=new Set(),patterns=new Set(),answers=new Set();const can=q=>{if(!q)return false;const root=q.rootFamily||q.family,pat=promptPattern(q);if(root&&roots.has(root))return false;if(pat&&patterns.has(pat))return false;if(q.correctText&&answers.has(q.correctText))return false;if(chosen.some(x=>promptSimilarity(x.q.prompt,q.prompt)>=.70))return false;return true};const add=(q,type,reason)=>{if(!can(q))return false;const root=q.rootFamily||q.family,pat=promptPattern(q);chosen.push({q,type,reason});if(root)roots.add(root);if(pat)patterns.add(pat);if(q.correctText)answers.add(q.correctText);return true};const pick=(arr,type,reason)=>{for(const q of arr.sort(()=>Math.random()-.5))if(add(q,type,typeof reason==='function'?reason(q):reason))return true;return false};const due=new Set(dueSkillKeys()),errKeys=[...new Set(s.errors.slice(-120).reverse().map(e=>{const q=qById(e.qid);return q?keySkill(q):null}).filter(Boolean))],known=Object.entries(s.skill).filter(([,v])=>v.done),weak=new Set(known.filter(([k,v])=>stageForSkillKey(k).level<3).sort((a,b)=>stageForSkillKey(a[0]).accuracy-stageForSkillKey(b[0]).accuracy).map(([k])=>k)),newPool=pool.filter(q=>!(s.skill[keySkill(q)]?.done));if(mode==='review'){for(const k of due)if(chosen.length<limit)pick(pool.filter(q=>keySkill(q)===k),'review','🕒 Revisão espaçada: veja se o conhecimento continuou com você.');for(const k of errKeys)if(chosen.length<limit)pick(pool.filter(q=>keySkill(q)===k),'error','🔁 Erro antigo: aplique a mesma habilidade em uma situação diferente.')}else{for(const k of [...due].slice(0,2))pick(pool.filter(q=>keySkill(q)===k),'review','🕒 Revisão espaçada: recuperar antes de esquecer.');for(const k of [...weak].slice(0,2))if(chosen.length<3)pick(pool.filter(q=>keySkill(q)===k),'weak','🧩 Ponto fraco: fortalecer uma habilidade que ainda não está estável.');if(chosen.length<4)pick(newPool,'new','🌱 Conteúdo novo: uma habilidade que você ainda não praticou.');const applyPool=pool.filter(q=>{const st=s.skill[keySkill(q)];return st?.done&&stageForSkillKey(keySkill(q)).level>=2&&!String(q.difficulty).toLowerCase().includes('fác')});if(chosen.length<5)pick(applyPool,'apply','🔄 Aplicação: usar o que você sabe em um problema novo.');const hard=pool.filter(q=>String(q.difficulty).toLowerCase().includes('dif')&&s.skill[keySkill(q)]?.done);if(chosen.length<6)pick(hard,'challenge','🚀 Desafio: testar transferência sem aumentar a quantidade de prática.');for(const k of errKeys)if(chosen.length<limit&&pick(pool.filter(q=>keySkill(q)===k),'error','🔁 Erro antigo: provar que o conceito foi aprendido, sem repetir a questão.'))break}const ranked=pool.sort((a,b)=>{const sa=stageForSkillKey(keySkill(a)).level,sb=stageForSkillKey(keySkill(b)).level;return sa-sb||Math.random()-.5});for(const q of ranked){if(chosen.length>=limit)break;add(q,'mix','🎯 Mistura inteligente: variedade real, sem repetir família ou padrão.')}return chosen.slice(0,limit)}
function startSmartStudy(mode='study'){const plan=smartPlan(mode,7);if(!plan.length)return alert('Não há questões realmente inéditas suficientes para montar uma sessão agora. A AEDS prefere parar a repetir modelos antigos.');ui.studySession={mode,items:plan.map(x=>({qid:x.q.id,type:x.type,reason:x.reason,result:null})),index:0,startedAt:Date.now(),finished:false};const q=plan[0].q;ui.page='train';ui.subject=q.subject;ui.grade=Number(q.grade);ui.area=q.area;ui.mathSkill=q.skill||'auto';ui.question=q;ui.selected=null;ui.cdf=null;ui.cid=null;ui.corrected=false;ui.hint=false;ui.started=Date.now();render()}
function advanceSmartStudy(){const ss=ui.studySession;if(!ss||ss.finished)return;ss.index++;if(ss.index>=ss.items.length){ss.finished=true;ss.finishedAt=Date.now();ui.question=null;render();return}const item=ss.items[ss.index],q=qById(item.qid);if(!q){ss.index--;ss.finished=true;render();return}ui.subject=q.subject;ui.grade=Number(q.grade);ui.area=q.area;ui.mathSkill=q.skill||'auto';ui.question=q;ui.selected=null;ui.cdf=null;ui.cid=null;ui.corrected=false;ui.hint=false;ui.started=Date.now();render()}
function smartSessionBanner(){const ss=ui.studySession;if(!ss||ss.finished)return'';const item=ss.items[ss.index];return `<div class="smart-session-banner"><div><b>Sessão curta · ${ss.index+1}/${ss.items.length}</b><small>${esc(item.reason)}</small></div><div class="session-dots">${ss.items.map((_,i)=>`<span class="${i<ss.index?'done':i===ss.index?'now':''}"></span>`).join('')}</div><button id="endSmartSession" class="btn btn-ghost">Encerrar</button></div>`}
function smartSessionFinishedHtml(){const ss=ui.studySession;if(!ss?.finished)return'';const done=ss.items.filter(x=>x.result!==null),right=done.filter(x=>x.result===true).length,mins=Math.max(1,Math.round(((ss.finishedAt||Date.now())-ss.startedAt)/60000));return `<section class="session-finish"><span class="session-finish-icon">🎒</span><h2>Sessão encerrada.</h2><p>Você fez <b>${done.length}</b> questões realmente diferentes em cerca de <b>${mins} min</b> e acertou <b>${right}</b>.</p><div class="autonomy-banner"><span>🚪</span><div><b>Agora saia da AEDS um pouco.</b><p>Tente usar uma dessas ideias na escola, no caderno, num livro ou explicando para alguém. Mais questões agora não significam necessariamente mais aprendizado.</p></div></div><div class="seg" style="justify-content:center"><button id="sessionHome" class="btn btn-primary">🏠 Voltar ao início</button><button id="sessionReview" class="btn btn-soft">🔁 Ver revisões</button></div></section>`}
function exportTriCalibration(){const rows=['student_id,qid,subject,grade,area,skill,difficulty,right,cdf,at,exam_id'];for(const u of state.users.filter(x=>x.role==='student'))for(const h of state.stats[u.id]?.history||[]){const q=qById(h.qid);if(!q)continue;rows.push([u.id,q.id,q.subject,q.grade,q.area,q.skill||'',q.difficulty||'',h.right?1:0,h.cdf||'',h.at||'',h.examId||''].map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(','))}download('aeds_tri_calibracao.csv',rows.join('\n'),'text/csv;charset=utf-8')}
function mathUnits(grade){return MATH_CURRICULUM?.[String(grade)]||[]}
function mathSkillsFor(grade,area){const fromMap=mathUnits(grade).find(x=>x.unit===area)?.skills||[],fromBank=[...new Set(candidateBank().filter(q=>q.subject==='Matemática'&&Number(q.grade)===Number(grade)&&q.area===area).map(q=>q.skill).filter(Boolean))];return [...new Set([...fromMap,...fromBank])]}
function recommendMathTarget(grade=ui.grade,area=null){const s=stats(),rows=[];for(const q of candidateBank()){if(q.subject!=='Matemática'||Number(q.grade)!==Number(grade)||(area&&q.area!==area)||q.questionType!=='multiple_choice'||!isQuestionFresh(q,s))continue;const k=keySkill(q),st=s.skill[k]||{done:0,correct:0,errors:0};const mastery=st.done?st.correct/st.done:0,priority=(st.done===0?100:0)+(st.errors*12)+(1-mastery)*60-Math.min(st.done,12)*2;rows.push({q,k,priority,done:st.done,mastery})}if(!rows.length)return null;rows.sort((a,b)=>b.priority-a.priority||a.done-b.done);const top=rows.slice(0,Math.min(12,rows.length));return top[Math.floor(Math.random()*top.length)].q}
function mathRoadmapHtml(grade){const s=stats(),units=mathUnits(grade);if(!units.length)return'';return `<div class="math-roadmap"><div class="math-roadmap-head"><div><b>Mapa Matemático AEDS</b><div class="tiny muted">Unidades → micro-habilidades → domínio individual. Trocar números não cria uma questão nova.</div></div><span class="pill">${units.reduce((n,u)=>n+u.skills.length,0)} habilidades</span></div><div class="math-unit-grid">${units.map(u=>{const vals=u.skills.map(sk=>{const keys=Object.keys(s.skill).filter(k=>k.startsWith(`Matemática|${grade}|${u.unit}|${sk}`));const done=keys.reduce((n,k)=>n+(s.skill[k]?.done||0),0),cor=keys.reduce((n,k)=>n+(s.skill[k]?.correct||0),0),m=done?Math.round(cor/done*100):0,count=candidateBank().filter(q=>q.subject==='Matemática'&&Number(q.grade)===Number(grade)&&q.area===u.unit&&q.skill===sk).length;return {sk,done,m,count}}),avg=vals.filter(x=>x.done).length?Math.round(vals.filter(x=>x.done).reduce((a,x)=>a+x.m,0)/vals.filter(x=>x.done).length):0;return `<div class="math-unit"><div class="math-unit-title"><div><b>${esc(u.unit)}</b><div class="tiny muted">${esc(u.description)}</div></div><span class="mastery-badge">${avg}%</span></div><div class="skill-cloud">${vals.map(x=>`<span class="skill-chip ${x.done?(x.m>=75?'skill-ok':x.m>=50?'skill-mid':'skill-low'):'skill-new'}" title="${x.count} questões · ${x.done} respondidas">${esc(x.sk)} · ${x.done?x.m+'%':'novo'}</span>`).join('')}</div></div>`}).join('')}</div></div>`}
function mathAreaDetailHtml(grade,area){const s=stats(),skills=mathSkillsFor(grade,area);if(!skills.length)return'';return `<div class="math-skill-list"><h3>Micro-habilidades desta unidade</h3><p class="muted">A AEDS mede cada habilidade separadamente. Para chegar a 🏆 Independente, é preciso aplicar, lembrar depois de alguns dias e provar que consegue fora da AEDS.</p>${skills.map(sk=>{const key=`Matemática|${grade}|${area}|${sk}`,st=s.skill[key]||AEDS_ENGINE.normalizeSkillStat({}),total=candidateBank().filter(q=>q.subject==='Matemática'&&Number(q.grade)===Number(grade)&&q.area===area&&q.skill===sk).length;return `<div class="math-skill-row"><div><b>${esc(sk)}</b><div class="tiny muted">${total} questões no banco · ${st.done} feitas · ${st.errors||0} erros · ${esc(AEDS_ENGINE.reviewLabel(st))}</div></div><div class="math-skill-actions">${stageBadge(key)}<button class="btn btn-soft trainSkill" data-subject="Matemática" data-area="${esc(area)}" data-skill="${esc(sk)}">Treinar</button></div></div>`}).join('')}</div>`}
function mathDiagnosisHtml(){const s=stats(),rows=Object.entries(s.skill).filter(([k,v])=>k.startsWith('Matemática|')&&v.done).map(([k,v])=>{const [sub,g,area,...sk]=k.split('|');return {g:Number(g),area,skill:sk.join('|'),done:v.done,errors:v.errors||0,mastery:Math.round((v.correct||0)/v.done*100)}});if(!rows.length)return `<div class="card math-diagnosis"><h3>Diagnóstico matemático</h3><div class="notice">Ainda não há dados por micro-habilidade. Faça algumas questões de Matemática e a AEDS vai separar exatamente onde você domina e onde precisa revisar.</div></div>`;const weak=[...rows].sort((a,b)=>a.mastery-b.mastery||b.errors-a.errors).slice(0,5),strong=[...rows].filter(x=>x.done>=2).sort((a,b)=>b.mastery-a.mastery||b.done-a.done).slice(0,5);return `<div class="card math-diagnosis"><div class="page-head" style="margin-bottom:10px"><div><h3 style="margin:0">Diagnóstico matemático por micro-habilidade</h3><div class="tiny muted">Não mistura conteúdos diferentes dentro de uma nota única.</div></div><span class="pill">${rows.length} habilidades medidas</span></div><div class="grid g2"><div><b>Prioridade de revisão</b><div class="list" style="margin-top:8px">${weak.map(x=>`<div class="item"><b>${esc(x.skill)}</b><div class="tiny muted">${gradeName(x.g)} · ${esc(x.area)} · ${x.done} feitas · ${x.errors} erros</div><div class="progress"><span style="width:${x.mastery}%"></span></div><div class="tiny">Domínio ${x.mastery}%</div></div>`).join('')}</div></div><div><b>Pontos fortes</b><div class="list" style="margin-top:8px">${strong.length?strong.map(x=>`<div class="item"><b>${esc(x.skill)}</b><div class="tiny muted">${gradeName(x.g)} · ${x.done} feitas</div><div class="progress"><span style="width:${x.mastery}%"></span></div><div class="tiny">Domínio ${x.mastery}%</div></div>`).join(''):'<div class="notice">Ainda faltam respostas suficientes para identificar pontos fortes.</div>'}</div></div></div></div>`}
function portUnits(grade){return PORT_CURRICULUM?.[String(grade)]||[]}
function portSkillsFor(grade,area){const fromMap=portUnits(grade).find(x=>x.unit===area)?.skills||[],fromBank=[...new Set(candidateBank().filter(q=>q.subject==='Português'&&Number(q.grade)===Number(grade)&&q.area===area).map(q=>q.skill).filter(Boolean))];return [...new Set([...fromMap,...fromBank])]}
function recommendPortTarget(grade=ui.grade,area=null){const s=stats(),rows=[];for(const q of candidateBank()){if(q.subject!=='Português'||Number(q.grade)!==Number(grade)||(area&&q.area!==area)||q.questionType!=='multiple_choice'||!isQuestionFresh(q,s))continue;const k=keySkill(q),st=s.skill[k]||{done:0,correct:0,errors:0};const mastery=st.done?st.correct/st.done:0,priority=(st.done===0?100:0)+(st.errors*14)+(1-mastery)*65-Math.min(st.done,10)*2;rows.push({q,k,priority,done:st.done,mastery})}if(!rows.length)return null;rows.sort((a,b)=>b.priority-a.priority||a.done-b.done);const top=rows.slice(0,Math.min(10,rows.length));return top[Math.floor(Math.random()*top.length)].q}
function portRoadmapHtml(grade){const s=stats(),units=portUnits(grade);if(!units.length)return'';return `<div class="math-roadmap"><div class="math-roadmap-head"><div><b>Mapa de Português AEDS</b><div class="tiny muted">Leitura → análise linguística → gêneros → argumentação. Cada micro-habilidade é medida separadamente.</div></div><span class="pill">${units.reduce((n,u)=>n+u.skills.length,0)} habilidades</span></div><div class="math-unit-grid">${units.map(u=>{const vals=u.skills.map(sk=>{const key=`Português|${grade}|${u.unit}|${sk}`,st=s.skill[key]||{done:0,correct:0},m=st.done?Math.round((st.correct||0)/st.done*100):0,count=candidateBank().filter(q=>q.subject==='Português'&&Number(q.grade)===Number(grade)&&q.area===u.unit&&q.skill===sk).length;return {sk,done:st.done||0,m,count}}),avg=vals.filter(x=>x.done).length?Math.round(vals.filter(x=>x.done).reduce((a,x)=>a+x.m,0)/vals.filter(x=>x.done).length):0;return `<div class="math-unit"><div class="math-unit-title"><div><b>${esc(u.unit)}</b><div class="tiny muted">${esc(u.description)}</div></div><span class="mastery-badge">${avg}%</span></div><div class="skill-cloud">${vals.map(x=>`<span class="skill-chip ${x.done?(x.m>=75?'skill-ok':x.m>=50?'skill-mid':'skill-low'):'skill-new'}" title="${x.count} questões · ${x.done} respondidas">${esc(x.sk)} · ${x.done?x.m+'%':'novo'}</span>`).join('')}</div></div>`}).join('')}</div></div>`}
function portAreaDetailHtml(grade,area){const s=stats(),skills=portSkillsFor(grade,area);if(!skills.length)return'';return `<div class="math-skill-list"><h3>Micro-habilidades desta unidade</h3><p class="muted">Português é avaliado pelo raciocínio usado no texto. Independência exige transferir a habilidade para textos que não vieram da AEDS.</p>${skills.map(sk=>{const key=`Português|${grade}|${area}|${sk}`,st=s.skill[key]||AEDS_ENGINE.normalizeSkillStat({}),total=candidateBank().filter(q=>q.subject==='Português'&&Number(q.grade)===Number(grade)&&q.area===area&&q.skill===sk).length;return `<div class="math-skill-row"><div><b>${esc(sk)}</b><div class="tiny muted">${total} questões ativas · ${st.done} feitas · ${st.errors||0} erros · ${esc(AEDS_ENGINE.reviewLabel(st))}</div></div><div class="math-skill-actions">${stageBadge(key)}<button class="btn btn-soft trainSkill" data-subject="Português" data-area="${esc(area)}" data-skill="${esc(sk)}">Treinar</button></div></div>`}).join('')}</div>`}
function portDiagnosisHtml(){const s=stats(),rows=Object.entries(s.skill).filter(([k,v])=>k.startsWith('Português|')&&v.done).map(([k,v])=>{const [sub,g,area,...sk]=k.split('|');return {g:Number(g),area,skill:sk.join('|'),done:v.done,errors:v.errors||0,mastery:Math.round((v.correct||0)/v.done*100)}});if(!rows.length)return `<div class="card math-diagnosis"><h3>Diagnóstico de Português</h3><div class="notice">Ainda não há dados por micro-habilidade. Faça questões de Português e a AEDS vai separar leitura, coesão, gramática em contexto, argumentação e revisão.</div></div>`;const weak=[...rows].sort((a,b)=>a.mastery-b.mastery||b.errors-a.errors).slice(0,5),strong=[...rows].filter(x=>x.done>=2).sort((a,b)=>b.mastery-a.mastery||b.done-a.done).slice(0,5);return `<div class="card math-diagnosis"><div class="page-head" style="margin-bottom:10px"><div><h3 style="margin:0">Diagnóstico de Português por micro-habilidade</h3><div class="tiny muted">Separa interpretação, gramática, coesão, gêneros e argumentação em vez de misturar tudo em uma nota.</div></div><span class="pill">${rows.length} habilidades medidas</span></div><div class="grid g2"><div><b>Prioridade de revisão</b><div class="list" style="margin-top:8px">${weak.map(x=>`<div class="item"><b>${esc(x.skill)}</b><div class="tiny muted">${gradeName(x.g)} · ${esc(x.area)} · ${x.done} feitas · ${x.errors} erros</div><div class="progress"><span style="width:${x.mastery}%"></span></div><div class="tiny">Domínio ${x.mastery}%</div></div>`).join('')}</div></div><div><b>Pontos fortes</b><div class="list" style="margin-top:8px">${strong.length?strong.map(x=>`<div class="item"><b>${esc(x.skill)}</b><div class="tiny muted">${gradeName(x.g)} · ${x.done} feitas</div><div class="progress"><span style="width:${x.mastery}%"></span></div><div class="tiny">Domínio ${x.mastery}%</div></div>`).join(''):'<div class="notice">Ainda faltam respostas suficientes para identificar pontos fortes.</div>'}</div></div></div></div>`}




// ---------- AEDS 9.0: aprofundamento ENEM por série ----------
function focusUnits(subject,grade){return FOCUS_CURRICULUM?.[subject]?.[String(grade)]||[]}
function focusSkillsFor(subject,grade,area){return focusUnits(subject,grade).find(x=>x.unit===area)?.skills||[]}
function focusRoadmapHtml(subject,grade){const units=focusUnits(subject,grade);if(!units.length)return'';const n=units.reduce((sum,u)=>sum+(u.skills?.length||0),0);return `<div class="math-roadmap enem-roadmap"><div class="math-roadmap-head"><div><b>🔥 Trilha ENEM 2026 — ${esc(subject)}</b><div class="tiny muted">O assunto grande foi quebrado em habilidades pequenas. Prioridade baseada em recorrência histórica e valor de base para a prova.</div></div><span class="pill">${n} aprofundamentos</span></div><div class="math-unit-grid">${units.map(u=>`<div class="math-unit"><div class="math-unit-title"><div><b>${esc(u.unit)}</b><div class="tiny muted">${esc(u.description)}</div></div><span class="mastery-badge enem-priority">${esc(u.priority||'Alta')}</span></div><div class="skill-cloud">${(u.skills||[]).map(sk=>`<span class="skill-chip skill-new">${esc(sk)}</span>`).join('')}</div></div>`).join('')}</div></div>`}
function focusAreaDetailHtml(subject,grade,area){const unit=focusUnits(subject,grade).find(x=>x.unit===area);if(!unit)return'';return `<div class="math-skill-list enem-area-detail"><div class="page-head" style="margin-bottom:8px"><div><h3 style="margin:0">🔥 Aprofundamento ENEM desta área</h3><div class="tiny muted">${esc(unit.description)}</div></div><span class="pill">Prioridade ${esc(unit.priority||'Alta')}</span></div>${(unit.skills||[]).map((sk,i)=>`<div class="math-skill-row"><div><b>${i+1}. ${esc(sk)}</b><div class="tiny muted">Micro-habilidade da trilha ${gradeName(grade)}</div></div><span class="mastery-badge">estudar</span></div>`).join('')}</div>`}
function learningSectionsHtml(d){if(!d?.sections?.length)return'';return d.sections.map(sec=>{const kind=esc(sec.kind||'concept'),pars=(sec.paragraphs||[]).map(x=>`<p>${esc(x)}</p>`).join(''),bul=(sec.bullets||[]).length?`<ul>${sec.bullets.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'';return `<section class="deep-section deep-${kind}"><h3>${esc(sec.title||'Aprofundamento')}</h3>${pars}${bul}</section>`}).join('')}
function cloudHeaders(token=cloudSession?.access_token){return {'apikey':CLOUD.anonKey,'Authorization':`Bearer ${token||CLOUD.anonKey}`,'Content-Type':'application/json'}}
function cloudStoreSession(){if(cloudSession)localStorage.setItem(CLOUD_SESSION_STORE,JSON.stringify(cloudSession));else localStorage.removeItem(CLOUD_SESSION_STORE)}
function cloudProfileFromRow(prof,email=''){return {id:prof.id,name:prof.name||prof.username||email.split('@')[0]||'Usuário',username:prof.username||email.split('@')[0]||'usuario',email,role:prof.role||'student',grade:Number(prof.grade)||5,blocked:!!prof.blocked,unlockedGrades:Array.isArray(prof.unlocked_grades)?prof.unlocked_grades.map(Number):[Number(prof.grade)||5],unlockedSubjects:Array.isArray(prof.unlocked_subjects)?prof.unlocked_subjects:[],examsUnlocked:prof.exams_unlocked!==false,password:''}}
async function cloudFetchJson(url,options={}){const timeoutMs=Number(options.timeoutMs)||window.AEDS_SYNC?.POLICY?.requestTimeoutMs||15000,controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeoutMs),fetchOptions={...options,signal:controller.signal};delete fetchOptions.timeoutMs;let r;try{r=await fetch(url,fetchOptions)}catch(cause){clearTimeout(timer);const e=new Error(cause?.name==='AbortError'?'Tempo limite da conexão excedido.':(cause?.message||'Falha de rede.'));e.status=0;e.retryAfterMs=0;e.cause=cause;throw e}clearTimeout(timer);let j=null;try{j=await r.json()}catch{}if(!r.ok){const msg=j?.msg||j?.message||j?.error_description||j?.error||`Erro ${r.status}`,e=new Error(msg);e.status=r.status;e.retryAfterMs=window.AEDS_SYNC?.parseRetryAfter(r.headers.get('Retry-After'))||0;throw e}return j}
async function cloudLoadProfile(){if(!cloudSession?.user?.id)return false;const rows=await cloudFetchJson(`${CLOUD.supabaseUrl}/rest/v1/profiles?select=*&id=eq.${encodeURIComponent(cloudSession.user.id)}`,{headers:cloudHeaders()});if(!rows?.[0])throw new Error('Perfil da conta não encontrado na AEDS.');const prof=rows[0];if(prof.blocked)throw new Error('Conta bloqueada pelo administrador.');const email=cloudSession.user.email||'';const patch=cloudProfileFromRow(prof,email);let u=state.users.find(x=>x.id===prof.id);if(u)Object.assign(u,patch);else state.users.push(patch);try{const ss=await cloudFetchJson(`${CLOUD.supabaseUrl}/rest/v1/user_state?select=state&profile_id=eq.${encodeURIComponent(prof.id)}`,{headers:cloudHeaders()});if(ss?.[0]?.state){const remote=ss[0].state;for(const k of Object.keys(remote)){if(k==='audit'||k==='auditV2')continue;state[k]=remote[k]}state.audit=Array.isArray(remote.auditV2)?remote.auditV2:[];normalize();u=state.users.find(x=>x.id===prof.id);if(u)Object.assign(u,patch);else state.users.push(patch)}}catch(e){console.warn('user_state',e)}state.currentUser=prof.id;localStorage.setItem(STORE,JSON.stringify(state));if(prof.role==='admin')setTimeout(cloudAdminRefresh,50);return true}
async function cloudLogin(email,password){if(!CLOUD.enabled||!CLOUD.supabaseUrl||!CLOUD.anonKey)return false;email=String(email||'').trim().toLowerCase();if(!email.includes('@'))throw new Error('Digite o e-mail completo da conta.');cloudSession=await cloudFetchJson(`${CLOUD.supabaseUrl}/auth/v1/token?grant_type=password`,{method:'POST',headers:{'apikey':CLOUD.anonKey,'Content-Type':'application/json'},body:JSON.stringify({email,password})});cloudStoreSession();const ok=await cloudLoadProfile();if(ok)cloudResumeSyncAfterAuth();return ok}
async function cloudRestoreSession(){if(!CLOUD.enabled)return false;let saved=null;try{let raw=localStorage.getItem(CLOUD_SESSION_STORE);if(!raw)for(const k of LEGACY_CLOUD_SESSION_STORES){raw=localStorage.getItem(k);if(raw)break}saved=JSON.parse(raw||'null')}catch{}if(!saved?.refresh_token){state.currentUser=null;return false}try{const now=Math.floor(Date.now()/1000);if(saved.access_token&&Number(saved.expires_at||0)>now+60){cloudSession=saved}else{cloudSession=await cloudFetchJson(`${CLOUD.supabaseUrl}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{'apikey':CLOUD.anonKey,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:saved.refresh_token})});cloudStoreSession()}const ok=await cloudLoadProfile();if(ok)cloudResumeSyncAfterAuth();return ok}catch(e){console.warn('restore session',e);cloudSession=null;cloudStoreSession();state.currentUser=null;return false}}
async function cloudLogout(){try{if(cloudSession?.access_token)await fetch(`${CLOUD.supabaseUrl}/auth/v1/logout`,{method:'POST',headers:cloudHeaders()})}catch{}cloudSession=null;cloudStoreSession();state.currentUser=null;localStorage.setItem(STORE,JSON.stringify(state));render()}
function cloudSaveSoon(){if(!CLOUD.enabled||!cloudSession)return;clearTimeout(cloudSaveTimer);const spread=900+Math.floor(Math.random()*4100);cloudSaveTimer=setTimeout(cloudPush,spread)}
async function cloudPush(){try{const u=me();if(!u||!cloudSession)return;const compact={stats:state.stats,topicDifficulty:state.topicDifficulty,prereqDone:state.prereqDone,independence:state.independence,feedback:(state.feedback||[]).filter(x=>!x.uid||x.uid===u.id),favorites:state.favorites,notes:state.notes,formulas:state.formulas,scratch:state.scratch,programDone:state.programDone,essays:state.essays,manualQueue:state.manualQueue,examHistory:state.examHistory,reviewQueue:state.reviewQueue,customQuestions:state.customQuestions,officialQuestions:state.officialQuestions,auditV2:state.audit,sessionDrafts:state.sessionDrafts,routine:state.routine,settings:state.settings};await cloudFetchJson(`${CLOUD.supabaseUrl}/rest/v1/user_state?on_conflict=profile_id`,{method:'POST',headers:{...cloudHeaders(),'Prefer':'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({profile_id:u.id,state:compact,updated_at:new Date().toISOString()})})}catch(e){console.warn('sync',e)}}
async function cloudProfileUpdate(profileId,patch){const rows=await cloudFetchJson(`${CLOUD.supabaseUrl}/rest/v1/profiles?id=eq.${encodeURIComponent(profileId)}`,{method:'PATCH',headers:{...cloudHeaders(),'Prefer':'return=representation'},body:JSON.stringify(patch)});if(!rows?.[0])throw new Error('A alteração não foi salva no Supabase. Saia e entre novamente como administrador.');return rows[0]}
async function cloudAdminAction(action,payload={}){if(!CLOUD.enabled||!cloudSession)throw new Error('Nuvem não conectada.');const r=await fetch(`${CLOUD.supabaseUrl}/functions/v1/${CLOUD.adminFunction||'admin-users'}`,{method:'POST',headers:cloudHeaders(),body:JSON.stringify({action,...payload})});let j={};try{j=await r.json()}catch{}if(!r.ok||!j.ok)throw new Error(j.error||'A função administrativa ainda não foi publicada no Supabase.');return j}
async function cloudAdminRefresh(){if(!CLOUD.enabled||!cloudSession||me()?.role!=='admin')return;try{const [profiles,states,subs]=await Promise.all([cloudFetchJson(`${CLOUD.supabaseUrl}/rest/v1/profiles?select=*`,{headers:cloudHeaders()}),cloudFetchJson(`${CLOUD.supabaseUrl}/rest/v1/user_state?select=profile_id,state`,{headers:cloudHeaders()}).catch(()=>[]),cloudFetchJson(`${CLOUD.supabaseUrl}/rest/v1/manual_submissions?select=*&order=created_at.desc&limit=200`,{headers:cloudHeaders()}).catch(()=>[])]);state.users=state.users.filter(u=>u.role==='admin'&&u.id===cloudSession.user.id);for(const prof of profiles){const patch=cloudProfileFromRow(prof,'');let u=state.users.find(x=>x.id===prof.id);if(u)Object.assign(u,patch);else state.users.push(patch)}state.feedback=[];for(const row of states){const rs=row.state||{},id=row.profile_id;if(rs.stats?.[id])state.stats[id]=rs.stats[id];if(rs.topicDifficulty?.[id])state.topicDifficulty[id]=rs.topicDifficulty[id];if(rs.prereqDone?.[id])state.prereqDone[id]=rs.prereqDone[id];if(rs.independence?.[id])state.independence[id]=rs.independence[id];if(Array.isArray(rs.feedback))state.feedback.push(...rs.feedback);if(rs.examHistory?.[id])state.examHistory[id]=rs.examHistory[id];if(rs.essays?.[id])state.essays[id]=rs.essays[id]}state.manualQueue=subs.map(x=>({id:x.id,cloudId:x.id,kind:x.kind,studentId:x.profile_id,studentName:state.users.find(u=>u.id===x.profile_id)?.name||'Aluno',prompt:x.prompt,answer:x.answer,status:x.status,score:x.score,comment:x.comment,createdAt:x.created_at}));normalize();localStorage.setItem(STORE,JSON.stringify(state));render()}catch(e){console.warn('admin refresh',e)}}
async function cloudSubmitManual(item){if(!CLOUD.enabled||!cloudSession)return;try{const rows=await cloudFetchJson(`${CLOUD.supabaseUrl}/rest/v1/manual_submissions`,{method:'POST',headers:{...cloudHeaders(),'Prefer':'return=representation'},body:JSON.stringify({profile_id:item.studentId,kind:item.kind,question_id:item.qid||item.essayId||null,prompt:item.prompt,answer:item.answer,status:'pending'})});if(rows?.[0])item.cloudId=rows[0].id}catch(e){console.warn('submission sync',e)}}
async function cloudGradeSubmission(item){if(!CLOUD.enabled||!cloudSession||!item.cloudId)return;try{await cloudFetchJson(`${CLOUD.supabaseUrl}/rest/v1/manual_submissions?id=eq.${encodeURIComponent(item.cloudId)}`,{method:'PATCH',headers:{...cloudHeaders(),'Prefer':'return=minimal'},body:JSON.stringify({status:'graded',score:item.score,comment:item.comment,graded_at:new Date().toISOString()})})}catch(e){console.warn('grade sync',e)}}
function cloudDifficultyToDb(d){return ({'fácil':'facil','médio':'medio','difícil':'dificil'})[d]||null}
function cloudDifficultyToUi(d){return ({facil:'fácil',medio:'médio',dificil:'difícil'})[d]||d||'médio'}
function cloudTypeToUi(t){return ({conteudo:'conteúdo',interpretacao:'interpretação',atencao:'atenção'})[t]||t||'conteúdo'}
function cloudQuestionToLocal(r){const opts=[r.option_a,r.option_b,r.option_c,r.option_d,r.option_e,r.option_f].filter(x=>x!==null&&x!==undefined&&String(x)!=='');return {id:`SUP-${r.id}`,remote:true,remoteId:r.id,subject:r.subject,grade:Number(r.grade),area:r.topic||'Geral',skill:r.subtopic||r.topic||'Geral',difficulty:cloudDifficultyToUi(r.difficulty),type:cloudTypeToUi(r.question_type),questionType:r.question_format==='discursiva'?'discursive':'multiple_choice',prompt:r.prompt||'',hint:r.hint||'',options:opts,correctIndex:null,correctText:'',explanation:'',explanationSteps:[],optionExplanations:[],references:[],origin:{type:'supabase',label:'Banco online',note:'Questão carregada do Supabase'},family:r.semantic_family||`sup:${r.id}`,rootFamily:r.semantic_family||`sup:${r.id}`,calculatorAllowed:false,prerequisite:'',media:r.image_url?{type:'image',src:r.image_url,title:'Imagem da questão',alt:'Imagem da questão'}:null,n:null,version:9}}
async function cloudTrainingBatch({subject,grade,area,difficulty}){const body={p_subject:subject,p_grade:Number(grade),p_topic:area||null,p_difficulty:difficulty?cloudDifficultyToDb(difficulty):null,p_limit:10};const rows=await cloudFetchJson(`${CLOUD.supabaseUrl}/rest/v1/rpc/get_training_questions`,{method:'POST',headers:cloudHeaders(),body:JSON.stringify(body)});return (rows||[]).map(cloudQuestionToLocal)}
async function cloudSubmitAnswer(q,selected,cdf,elapsedMs){const rows=await cloudFetchJson(`${CLOUD.supabaseUrl}/rest/v1/rpc/submit_answer`,{method:'POST',headers:cloudHeaders(),body:JSON.stringify({p_question_id:q.remoteId,p_selected_answer:LETTERS[selected],p_cdf:cdf,p_cid:null,p_response_time_seconds:Math.max(1,elapsedMs)/1000})});const row=rows?.[0];if(!row)throw new Error('O Supabase não devolveu a correção.');return row}
async function cloudSetAnswerCID(q,v){const map={Conteudo:'conteudo',Interpretacao:'interpretacao',Distracao:'distracao'};await cloudFetchJson(`${CLOUD.supabaseUrl}/rest/v1/rpc/set_answer_cid`,{method:'POST',headers:cloudHeaders(),body:JSON.stringify({p_question_id:q.remoteId,p_cid:map[v]})})}

// ---------- data decoding ----------
async function decodeDataLegacy829(){if(!window.ESTUDAPLUS_BANK_B64)throw new Error('Arquivo bank-data.js não encontrado. Mantenha bank-data.js junto do index.html.');if(!('DecompressionStream' in window))throw new Error('Seu navegador precisa ser Chrome, Edge ou Opera atualizado para abrir o banco local.');const bin=atob(window.ESTUDAPLUS_BANK_B64),bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));const text=await new Response(stream).text();DATA=JSON.parse(text);BANK=DATA.questions;CREDITS=DATA.credits;LEARNING=DATA.learning;LEARNING_BY_GRADE=DATA.learningByGrade||{};PROGRAMMING=DATA.programming;MANIFEST=DATA.manifest;PREREQ=DATA.prerequisites;MATH_CURRICULUM=DATA.mathCurriculum||{};PORT_CURRICULUM=DATA.portugueseCurriculum||{};FOCUS_CURRICULUM=DATA.focusCurriculum||{};ESSAY_REPERTOIRE=DATA.essayRepertoire||{};QMAP=new Map(BANK.map(q=>[q.id,q]));CREDIT_MAP=new Map(CREDITS.map(c=>[c.id,c]));state=loadState();normalize();if(CLOUD.enabled)await cloudRestoreSession();else restoreSessionDraft();render()}

