const NAV=[['home','🏠','Início'],['learn','📘','Aprender'],['train','🎯','Treinar'],['exam','📝','Provas'],['review','🔁','Revisar'],['essay','✍️','Redação'],['performance','📊','Progresso'],['favorites','⭐','Favoritos'],['formulas','🧮','Fórmulas'],['program','💻','Programação'],['science','🔬','Ciência'],['routine','🗓️','Rotina'],['sources','🔎','Fontes'],['official','🏛️','Banco oficial'],['settings','⚙️','Configurações']];
function sidebar(){const m=me(),items=m.role==='admin'?[['admin','🛠️','Admin'],...NAV]:NAV,primaryKeys=['home','learn','train','exam'],primary=items.filter(x=>primaryKeys.includes(x[0])),more=items.filter(x=>!primaryKeys.includes(x[0])),moreActive=more.some(x=>x[0]===ui.page),starter=items.filter(x=>primaryKeys.includes(x[0])),tools=items.filter(x=>!primaryKeys.includes(x[0]));return `<aside class="sidebar"><div class="brand"><div class="brand-mark">A</div><div><h2>AEDS</h2><div class="muted tiny">A Evolução do Saber · V9.0.13</div></div></div><div class="desktop-nav"><div class="nav-section">Começar</div>${starter.map(x=>`<button class="nav nav-visual ${ui.page===x[0]?'active':''}" data-page="${x[0]}" aria-label="${x[2]}"><span class="ico">${x[1]}</span><span class="label">${x[2]}</span></button>`).join('')}<div class="nav-section">Mais</div>${tools.map(x=>`<button class="nav ${ui.page===x[0]?'active':''}" data-page="${x[0]}" aria-label="${x[2]}"><span class="ico">${x[1]}</span><span class="label">${x[2]}</span></button>`).join('')}<div class="nav-section">Conta</div><button class="nav" id="logout"><span class="ico">🚪</span><span class="label">Sair</span></button></div><div class="mobile-nav">${primary.map(x=>`<button class="nav ${ui.page===x[0]?'active':''}" data-page="${x[0]}" aria-label="${x[2]}"><span class="ico">${x[1]}</span><span class="label">${x[2]}</span></button>`).join('')}<details class="mobile-more"><summary class="nav ${moreActive?'active':''}"><span class="ico">☰</span><span class="label">Mais</span></summary><div class="mobile-more-sheet"><div class="mobile-more-head"><div><b>Escolha pela figura</b><div class="tiny muted">Toque em uma opção</div></div><button type="button" class="mobile-more-close" id="mobileMoreClose" aria-label="Fechar menu">×</button></div><div class="mobile-more-grid">${more.map(x=>`<button class="mobile-more-item ${ui.page===x[0]?'active':''}" data-page="${x[0]}" aria-label="${x[2]}"><span class="ico">${x[1]}</span><span>${x[2]}</span></button>`).join('')}<button class="mobile-more-item danger-link" id="mobileLogout"><span class="ico">🚪</span><span>Sair</span></button></div></div></details></div></aside>`}
function shell(body){const m=me(),pm=PAGE_VISUAL[ui.page]||PAGE_VISUAL.home;return `<div class="shell">${sidebar()}<main class="main"><header class="topbar"><div class="page-identity" title="${pm.label}"><span>${pm.icon}</span><b>${pm.label}</b></div><div class="searchbox"><input id="globalSearch" value="${esc(ui.search)}" placeholder="🔎 Procurar..."><div id="searchResults" class="search-results ${ui.searchOpen?'':'hidden'}"></div></div><div class="top-actions"><button id="speakPage" class="btn btn-listen no-print" title="Ouvir esta tela" aria-label="Ouvir esta tela">🔊 <span>Ouvir</span></button><button id="focusBtn" class="btn btn-ghost no-print" title="Modo foco">◎ <span>Foco</span></button><div class="user-chip"><div class="avatar">${esc(m.name[0])}</div><div class="user-text"><b class="small">${esc(m.name)}</b><div class="tiny muted">${m.role==='admin'?'Administrador':gradeName(m.grade)}</div></div></div></div></header><section class="content">${body}<div class="footer">AEDS — A Evolução do Saber · V9.0.13 · ${CLOUD.enabled?'nuvem ativa':'modo local'}</div></section></main></div>`}
function metric(label,value,sub=''){return `<div class="card"><div class="metric-label">${label}</div><div class="metric">${value}</div><div class="muted small">${sub}</div></div>`}
function availableSubjects(u=targetStudent()){const all=Object.keys(MANIFEST.subjects);if(me()?.role==='admin')return all;if(!u)return[];if(!Array.isArray(u.unlockedSubjects))return all;return all.filter(s=>u.unlockedSubjects.includes(s))}
function availableGrades(subject,u=targetStudent()){const all=Object.keys(MANIFEST.subjects[subject]?.grades||{}).map(Number).sort((a,b)=>a-b);if(me()?.role==='admin')return all;if(!u)return[];const allowed=Array.isArray(u.unlockedGrades)?u.unlockedGrades:[u.grade];return all.filter(g=>allowed.includes(g))}
function manifestAreas(subject,grade){const g=MANIFEST.subjects?.[subject]?.grades?.[String(grade)]||{};return g&&typeof g==='object'&&g.areas&&typeof g.areas==='object'?g.areas:g}function areasFor(subject,grade){return Object.keys(manifestAreas(subject,grade))}

