const ESSAY_COURSE_MODULES=[
{id:'proposta',title:'1. Entender a proposta e fazer o recorte',goal:'Saber exatamente o que o tema pede antes de pensar em repertório.',why:'Uma redação pode ser bem escrita e ainda perder muitos pontos se responder a um tema parecido, mas não ao recorte apresentado.',method:['Circule mentalmente o núcleo do tema: problema + grupo + espaço + recorte.','Transforme o tema em uma pergunta: “por que isso acontece?” ou “o que impede a solução?”.','Escolha um recorte que possa ser defendido em cerca de 30 linhas.'],mistakes:['Responder ao assunto geral e esquecer o recorte.','Copiar a coletânea em vez de formular uma leitura própria.','Começar a escrever antes de decidir a tese.'],example:'Tema: “Desafios para combater a desinformação no Brasil”. Recorte possível: a baixa educação midiática e o incentivo algorítmico a conteúdos enganosos.'},
{id:'tese',title:'2. Construir uma tese forte',goal:'Transformar opinião vaga em uma linha de raciocínio que organize o texto inteiro.',why:'A tese funciona como promessa do texto: os parágrafos seguintes precisam provar o que ela anuncia.',method:['Declare sua posição sobre o problema.','Escolha dois eixos argumentativos diferentes.','Verifique se cada eixo pode virar um parágrafo próprio.'],mistakes:['Tese genérica: “esse problema precisa ser resolvido”.','Listar causas sem indicar relação com o tema.','Mudar de posição no meio do texto.'],example:'“A persistência da desinformação decorre tanto da fragilidade da educação midiática quanto de incentivos digitais que premiam conteúdos de alto engajamento.”'},
{id:'introducao',title:'3. Introdução sem fórmula decorada',goal:'Contextualizar, apresentar o recorte e chegar à tese sem desperdiçar linhas.',why:'Uma boa introdução orienta o corretor; uma introdução ornamental consome espaço sem construir argumento.',method:['Contextualize em 1 ou 2 frases.','Faça a ponte entre o contexto e o tema.','Feche com a tese e os dois eixos que serão desenvolvidos.'],mistakes:['Começar com frase pronta sem função.','Usar citação e não explicar a relação com o tema.','Esconder a tese em um parágrafo muito longo.'],example:'Você pode começar por fato histórico, conceito, contraste, definição ou cenário atual — desde que isso leve diretamente ao problema.'},
{id:'desenvolvimento',title:'4. Desenvolvimento e tópico frasal',goal:'Construir cada parágrafo ao redor de uma única ideia central.',why:'O desenvolvimento não é um depósito de repertórios; é uma cadeia de raciocínio.',method:['Tópico frasal: apresente o argumento do parágrafo.','Explique o mecanismo: como e por que isso produz o problema.','Traga evidência ou repertório pertinente.','Analise a evidência e conecte-a à tese.','Feche o parágrafo sem repetir a introdução.'],mistakes:['Colocar duas ideias centrais sem conexão.','Citar dado e seguir adiante sem interpretar.','Terminar o parágrafo sem mostrar sua relação com a tese.'],example:'Argumento: falta de educação midiática. Depois explique como ela reduz a capacidade de verificar fontes, traga uma evidência e mostre a consequência social.'},
{id:'argumentos',title:'5. Argumentar de verdade',goal:'Escolher a estratégia que prova o ponto, em vez de apenas enfeitar o texto.',why:'Argumento forte não depende do nome da estratégia; depende da relação lógica entre evidência e conclusão.',method:['Autoridade: use fonte pertinente e explique sua contribuição.','Exemplificação: use caso concreto como evidência, não como prova universal.','Comparação: explicite o critério comparado.','Causa e consequência: mostre o mecanismo que liga uma coisa à outra.','Dados: cite fonte confiável e interprete o número.','Alusão histórica: mostre semelhança e diferença com o presente.'],mistakes:['Confundir correlação com causalidade.','Usar autoridade fora da área.','Generalizar a partir de um único caso.','Inventar estatísticas ou leis.'],example:'“Após X, ocorreu Y” não prova que X causou Y. É preciso mostrar o mecanismo ou controlar outras explicações possíveis.'},
{id:'repertorio',title:'6. Repertório sociocultural produtivo',goal:'Usar conhecimento externo para fazer o argumento avançar.',why:'Repertório só vale quando é pertinente, legitimado e conectado ao raciocínio.',method:['Escolha uma referência que realmente dialogue com o eixo do parágrafo.','Apresente apenas o aspecto necessário da obra, dado ou conceito.','Explique a ponte entre referência e problema atual.','Retorne ao argumento do parágrafo.'],mistakes:['“Repertório de bolso” que cabe em qualquer tema.','Citação solta.','Referência falsa ou imprecisa.','Resumo longo de filme/livro sem análise.'],example:'Em vez de apenas citar “1984”, explique qual mecanismo de vigilância/manipulação da obra ajuda a compreender o problema discutido.'},
{id:'coesao',title:'7. Coesão e conectivos com função',goal:'Fazer o leitor enxergar as relações entre as ideias.',why:'Conectivo não melhora texto sozinho. Ele precisa corresponder à relação lógica real.',method:['Adição: além disso, também, ainda.','Contraste: porém, contudo, entretanto.','Causa: porque, visto que, em razão de.','Consequência: portanto, por isso, desse modo.','Exemplificação: por exemplo, como se observa em.','Conclusão: portanto, diante disso, assim.'],mistakes:['Começar todo parágrafo com o mesmo conectivo.','Usar “portanto” sem consequência lógica.','Empilhar palavras rebuscadas que não combinam com a frase.'],example:'Se a segunda frase contradiz parcialmente a primeira, “entretanto” pode funcionar; se apenas acrescenta informação, ele está errado.'},
{id:'falacias',title:'8. Contra-argumentação e falácias',goal:'Reconhecer raciocínios frágeis e tornar a defesa mais resistente.',why:'Uma redação forte antecipa objeções plausíveis e evita atalhos lógicos.',method:['Pergunte qual evidência sustentaria seu argumento.','Procure explicações alternativas.','Evite ladeira escorregadia, falsa causa, generalização apressada e falso dilema.','Quando útil, reconheça um benefício ou limite antes de defender sua posição.'],mistakes:['Tratar consequência extrema como inevitável.','Reduzir debate complexo a duas opções.','Atacar pessoas em vez de ideias.'],example:'“Se estudantes usarem IA em uma tarefa, logo ninguém mais pensará” é uma projeção extrema sem demonstrar as etapas que tornariam isso inevitável.'},
{id:'intervencao',title:'9. Proposta de intervenção completa',goal:'Propor uma resposta concreta ao problema que o próprio texto desenvolveu.',why:'A conclusão precisa nascer dos argumentos, e não de uma solução genérica encaixada no final.',method:['Ação: o que será feito?','Agente: quem tem competência para executar?','Modo/meio: como a ação ocorrerá?','Efeito/finalidade: para quê?','Detalhamento: torne algum elemento mais específico.'],mistakes:['“O governo deve resolver”.','Agente sem competência para a ação.','Intervenção desconectada dos dois desenvolvimentos.','Proposta que viola direitos humanos.'],example:'“O MEC, em parceria com redes de ensino, deve implementar oficinas de educação midiática, por meio de atividades de verificação de fontes, para ampliar a capacidade de estudantes identificarem desinformação.”'},
{id:'competencias',title:'10. Revisar pelas 5 competências',goal:'Trocar a pergunta “ficou bonito?” por critérios objetivos de revisão.',why:'No ENEM 2026, cada competência recebe de 0 a 200 pontos e a nota pode chegar a 1.000.',method:['C1: procure desvios de escrita formal que prejudiquem clareza.','C2: confira tema, tipo textual e repertório pertinente.','C3: teste se os argumentos realmente defendem a tese.','C4: verifique coesão entre frases e parágrafos.','C5: confirme intervenção relacionada ao problema e respeitosa aos direitos humanos.'],mistakes:['Revisar apenas ortografia.','Achar que repertório difícil compensa argumento fraco.','Inserir proposta pronta sem conexão com o desenvolvimento.'],example:'Faça duas revisões: primeiro conteúdo/argumentação; depois língua/cohesão. Misturar tudo numa única leitura costuma esconder erros.'},
{id:'planejamento',title:'11. Projeto de texto em 5 minutos',goal:'Planejar antes de escrever para reduzir contradições e repetição.',why:'Um esqueleto curto economiza tempo de reescrita e ajuda a manter unidade textual.',method:['Tema/recorte em uma frase.','Tese em uma frase.','Argumento 1 + evidência.','Argumento 2 + evidência.','Intervenção ligada aos problemas discutidos.'],mistakes:['Planejamento longo demais.','Decidir repertório antes de decidir argumento.','Criar três ou quatro desenvolvimentos sem espaço para aprofundar.'],example:'Se você não consegue resumir sua tese em uma frase, ainda não está pronto para começar o texto.'},
{id:'autonomia',title:'12. Reescrever até não depender da AEDS',goal:'Transferir o aprendizado para uma folha, escola, professor ou outra plataforma.',why:'A AEDS cumpriu seu papel quando você consegue planejar, escrever e revisar sem consultar um modelo.',method:['Escreva uma versão com ajuda.','Leia a correção e identifique 2 ou 3 padrões de erro.','Reescreva sem olhar a versão anterior.','Faça um novo tema em papel, com tempo limitado e sem consultar a AEDS.'],mistakes:['Colecionar modelos sem escrever.','Corrigir e nunca reescrever.','Decorar uma introdução universal.'],example:'Seu teste final é conseguir explicar sua tese, dois argumentos e intervenção em voz alta antes de escrever.'}
];
const ESSAY_DRILLS=[
{q:'Um texto afirma que, depois da adoção de aulas híbridas, a evasão aumentou; logo, o ensino híbrido causou a evasão. Qual é a fragilidade?',opts:['Falta de conectivo','Relação causal não demonstrada','Ausência de citação','Uso de linguagem formal'],a:1,why:'Dois acontecimentos próximos no tempo não bastam para provar causa. É preciso considerar outros fatores e explicar o mecanismo.'},
{q:'Qual tese é mais útil para organizar uma redação sobre desinformação?',opts:['A desinformação é um problema muito grave.','Todos precisam se conscientizar.','A desinformação se mantém pela baixa educação midiática e por incentivos de circulação nas plataformas.','As fake news existem há muito tempo.'],a:2,why:'Ela apresenta posição e dois eixos distintos que podem ser desenvolvidos.'},
{q:'Quando um argumento de autoridade é forte?',opts:['Quando o nome citado é famoso.','Quando a pessoa ou instituição é pertinente ao assunto e a referência é conectada ao argumento.','Quando substitui a explicação do autor.','Quando aparece entre aspas.'],a:1,why:'Autoridade relevante reforça uma ideia; não elimina a necessidade de explicar a relação com o tema.'},
{q:'Qual uso de repertório é mais produtivo?',opts:['Citar uma obra conhecida e seguir para outro assunto.','Resumir o enredo inteiro de um filme.','Explicar o aspecto da obra que ilumina o problema discutido e voltar ao argumento.','Usar sempre a Constituição, independentemente do tema.'],a:2,why:'Repertório produtivo participa do raciocínio; não serve como decoração.'},
{q:'Qual tópico frasal funciona melhor para um desenvolvimento sobre exclusão digital?',opts:['Segundo dados do IBGE...','A falta de infraestrutura digital amplia desigualdades educacionais ao limitar o acesso regular a recursos de aprendizagem.','Além disso, portanto, entretanto...','A tecnologia é importante desde sempre.'],a:1,why:'Ele anuncia a ideia central do parágrafo e já mostra sua relação causal com o problema.'},
{q:'Se uma frase acrescenta outro motivo ao argumento anterior, qual relação lógica o conectivo deve expressar?',opts:['Contraste','Adição','Conclusão','Condição'],a:1,why:'Escolher conectivo pela função evita coesão apenas aparente.'},
{q:'Uma conclusão diz apenas “a sociedade precisa agir”. O principal problema é:',opts:['Falta de linguagem formal','Agente e ação vagos','Excesso de repertório','Uso de primeira pessoa'],a:1,why:'A intervenção precisa indicar de forma concreta quem faz o quê e como essa ação enfrenta o problema.'},
{q:'“Se estudantes usarem IA para pequenas tarefas, inevitavelmente deixarão de pensar e a educação acabará.” Esse raciocínio exemplifica:',opts:['Analogia precisa','Ladeira escorregadia','Argumento estatístico','Definição'],a:1,why:'A conclusão extrema é apresentada como inevitável sem demonstrar as etapas intermediárias.'},
{q:'Qual sequência descreve melhor um parágrafo argumentativo?',opts:['Citação → citação → conclusão','Tópico frasal → explicação → evidência/repertório → análise → síntese','Pergunta → lista → opinião','Conectivo → dado → novo tema'],a:1,why:'Essa sequência mantém uma ideia central e mostra como a evidência sustenta o argumento.'},
{q:'O que deve orientar a proposta de intervenção?',opts:['Uma solução que sirva para qualquer redação.','O problema realmente desenvolvido nos parágrafos anteriores.','O repertório usado na introdução, mesmo sem relação com a tese.','O agente mais conhecido pelo candidato.'],a:1,why:'A intervenção fecha o raciocínio; portanto, deve responder às causas, obstáculos ou consequências discutidos.'}
];
function essayAcademyHtml(){return `<section class="essay-academy"><div class="page-head"><div><h2>Curso de Redação ENEM</h2><div class="muted">Aprenda a pensar o texto. Nada de decorar uma introdução universal.</div></div><span class="pill">12 módulos</span></div><div class="essay-module-grid">${ESSAY_COURSE_MODULES.map((m,i)=>`<details class="card essay-module" ${i===0?'open':''}><summary><b>${esc(m.title)}</b><span class="muted small">${esc(m.goal)}</span></summary><div class="essay-module-body"><p><b>Por que isso importa:</b> ${esc(m.why)}</p><h4>Como fazer</h4><ol>${m.method.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h4>Erros comuns</h4><ul>${m.mistakes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="notice"><b>Exemplo:</b> ${esc(m.example)}</div></div></details>`).join('')}</div><div class="card" style="margin-top:14px"><h3>Microtreino de argumentação</h3><p class="muted small">Responda mentalmente antes de abrir a explicação.</p><div class="essay-drills">${ESSAY_DRILLS.map((d,i)=>`<details class="item"><summary><b>${i+1}. ${esc(d.q)}</b></summary><ol type="A">${d.opts.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="success"><b>Resposta:</b> ${String.fromCharCode(65+d.a)}. ${esc(d.why)}</div></details>`).join('')}</div></div><div class="card" style="margin-top:14px"><h3>Conectivos: escolha pela relação lógica</h3><div class="grid g3"><div><b>Adicionar</b><p class="small">além disso · também · ainda</p></div><div><b>Contrastar</b><p class="small">porém · contudo · entretanto</p></div><div><b>Explicar causa</b><p class="small">porque · visto que · em razão de</p></div><div><b>Mostrar consequência</b><p class="small">portanto · por isso · desse modo</p></div><div><b>Exemplificar</b><p class="small">por exemplo · como se observa em</p></div><div><b>Concluir</b><p class="small">portanto · diante disso · assim</p></div></div><div class="warning"><b>Regra:</b> não escolha conectivo porque ele parece sofisticado. Escolha porque ele descreve a relação real entre as ideias.</div></div><div class="card" style="margin-top:14px"><h3>Escala das competências</h3><p>Cada competência pode receber <b>0, 40, 80, 120, 160 ou 200 pontos</b>. Use essa escala para revisar, mas não tente “caçar pontos” mecanicamente: primeiro construa um texto coerente.</p>${refsHtml(['inep_redacao_2026'])}</div></section>`}

function essayThemeByTitle(title){return ESSAY_THEMES.find(x=>x.title===title)||ESSAY_THEMES[0]}
function essayThemesHtml(){return `<div class="theme-bank">${ESSAY_THEMES.map(t=>`<div class="theme-card ${ui.essayPrompt===t.title?'active':''}"><div class="theme-number">${String(t.n).padStart(2,'0')}</div><div class="theme-copy"><b>${esc(t.title)}</b><div class="muted small">${esc(t.axis)}</div></div><button class="btn btn-soft essayThemeBtn" data-theme="${t.n}">Treinar este tema</button></div>`).join('')}</div>`}
function essayGuideHtml(){return `<div class="card"><h3>As 5 competências do ENEM 2026</h3><ol><li><b>Competência 1:</b> domínio da modalidade escrita formal.</li><li><b>Competência 2:</b> compreensão da proposta, manutenção do texto dissertativo-argumentativo e repertório pertinente.</li><li><b>Competência 3:</b> seleção, relação, organização e interpretação de informações e argumentos.</li><li><b>Competência 4:</b> mecanismos linguísticos necessários à construção da argumentação e da coesão.</li><li><b>Competência 5:</b> proposta de intervenção relacionada ao problema e respeitosa aos direitos humanos.</li></ol><div class="notice">Cada competência vale até 200 pontos. A redação pode chegar a 1.000. A Cartilha do Participante 2026 também lembra que o texto tem até 30 linhas e deve responder ao recorte temático proposto.</div><h3>Os 5 elementos da intervenção</h3><div class="steps"><div class="step"><b>Agente:</b> quem executa.</div><div class="step"><b>Ação:</b> o que será feito.</div><div class="step"><b>Modo/meio:</b> como será executado.</div><div class="step"><b>Efeito:</b> para quê / qual resultado se espera.</div><div class="step"><b>Detalhamento:</b> informação adicional que torna um dos elementos mais específico.</div></div><div class="warning">Não adianta encaixar cinco elementos mecanicamente. A intervenção precisa enfrentar um problema realmente discutido no texto e ser plausível.</div><h3>Checklist antes de enviar</h3><ul><li>O tema e o recorte aparecem claramente?</li><li>Minha tese define uma linha de raciocínio?</li><li>Cada desenvolvimento acrescenta algo novo?</li><li>O repertório foi explicado e conectado ao argumento?</li><li>Há coesão sem repetição mecânica de conectivos?</li><li>A intervenção responde às causas ou obstáculos discutidos?</li><li>Revisei concordância, pontuação, regência, pronomes e ortografia?</li></ul>${refsHtml(['inep_redacao_2026'])}</div>`}
function essayRepertoireHtml(){const b=ESSAY_REPERTOIRE?.brasil_pais_do_futuro;if(!b)return'';return `<details class="card repertoire-book" open><summary><span class="repertoire-book-icon">📚</span><span><b>Livro-guia: ${esc(b.title)}</b><small>${esc(b.author)} · ${b.year} · repertório crítico para redação</small></span><span class="pill">aprofundado</span></summary><div class="repertoire-body"><p>${esc(b.intro)}</p><div class="grid g2"><div><h3>Contexto que você precisa saber</h3><ul>${(b.context||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div><h3>Ideias que podem virar argumento</h3><ul>${(b.theses||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div><h3>Onde esse repertório pode funcionar</h3><div class="repertoire-axis-grid">${(b.axes||[]).map(x=>`<div class="item"><b>${esc(x.axis)}</b><p class="small">${esc(x.use)}</p></div>`).join('')}</div><h3>Leitura crítica — parte obrigatória</h3><ul>${(b.critical_reading||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Como colocar no texto sem virar frase pronta</h3><div class="steps">${(b.method||[]).map(x=>`<div class="step">${esc(x)}</div>`).join('')}</div><div class="grid g2"><div class="warning"><b>Uso fraco</b><p>${esc(b.bad_use)}</p></div><div class="notice"><b>Uso produtivo</b><p>${esc(b.good_use)}</p></div></div><h3>Temas para praticar este repertório</h3><ol>${(b.practice_prompts||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="warning"><b>Importante:</b> a AEDS traz um dossiê autoral de estudo da obra e links de referência. Ela não reproduz uma tradução integral do livro. Para o ENEM, compreender e relacionar criticamente o repertório é mais útil do que decorar trechos.</div><h3>Fontes para aprofundar</h3>${refsHtml(b.references||[])}</div></details>`}

function essayModelsHtml(){return `<div class="card"><h3>O que observar em redações nota mil</h3><p class="muted small">Síntese autoral dos exemplos de 2022 a 2025 enviados como referência. Os textos integrais não são reproduzidos.</p><div class="list">${ESSAY_NOTE_MIL.map(x=>`<div class="item"><b>ENEM ${x.year}</b><div class="small">${esc(x.theme)}</div><p class="muted small">${esc(x.lesson)}</p></div>`).join('')}</div><h4>Padrão de estrutura útil</h4><div class="steps"><div class="step">Introdução: contextualize, apresente o tema e feche com uma tese clara.</div><div class="step">Desenvolvimento 1: apresente uma causa ou obstáculo, explique e conecte um repertório pertinente.</div><div class="step">Desenvolvimento 2: trabalhe outro aspecto do problema sem repetir o primeiro.</div><div class="step">Conclusão: agente + ação + meio/modo + finalidade + detalhamento quando necessário.</div></div><div class="warning">Não invente dados, leis, pesquisas ou repertórios. Um repertório simples e corretamente relacionado vale mais do que uma referência falsa ou decorada sem ligação com a tese.</div></div>`}
function essayView(){const u=targetStudent(),list=state.essays[u.id];if(!ui.essayPrompt||!ESSAY_PROMPTS.includes(ui.essayPrompt))ui.essayPrompt=ESSAY_PROMPTS[list.length%ESSAY_PROMPTS.length];const theme=essayThemeByTitle(ui.essayPrompt),draft=list.find(x=>x.status==='draft'&&x.prompt===ui.essayPrompt);if(!ui.essayStarted)ui.essayStarted=draft?.startedAt||Date.now();return `<div class="page-head"><div><h1>Redação</h1><div class="muted">${ESSAY_THEMES.length} temas de treino + curso completo de argumentação + critérios oficiais do ENEM 2026.</div></div><div class="timer" id="essayTimer">00:00:00</div></div>${essayAcademyHtml()}${essayRepertoireHtml()}<div class="grid g2" style="margin-top:14px"><div class="card"><div class="qmeta"><span class="tag">Tema ${String(theme.n).padStart(2,'0')}</span><span class="tag">${esc(theme.axis)}</span></div><h3 style="margin-top:12px">${esc(theme.title)}</h3><p class="muted">Produza um texto dissertativo-argumentativo em prosa. Apresente tese, argumentos coerentes, repertório pertinente e proposta de intervenção respeitando os direitos humanos.</p><div class="field"><label>Redação</label><textarea id="essayText" class="essay-editor">${esc(draft?.text||'')}</textarea></div><div class="seg"><button id="saveEssay" class="btn btn-soft">Salvar rascunho</button><button id="submitEssay" class="btn btn-primary">Enviar para correção</button><button id="newEssayPrompt" class="btn btn-ghost">Outro tema</button></div></div>${essayGuideHtml()}</div><div class="grid g2" style="margin-top:14px">${essayModelsHtml()}<div class="card"><h3>Seu histórico</h3><div class="list">${list.slice().reverse().map(x=>`<div class="item"><b>${esc(x.prompt)}</b><div class="muted small">${x.status} · ${new Date(x.updatedAt).toLocaleString('pt-BR')} ${x.score!=null?`· nota ${x.score}`:''}</div></div>`).join('')||'<div class="muted">Nenhuma redação ainda.</div>'}</div><div class="notice" style="margin-top:12px"><b>Dica de prática:</b> escreva, corrija e reescreva. Compare a nova versão com a anterior e registre quais erros deixaram de aparecer.</div></div></div><div class="page-head" style="margin-top:18px"><div><h2>Banco de ${ESSAY_THEMES.length} temas</h2><div class="muted">Escolha um tema e comece a treinar sem precisar ficar clicando em “Outro tema”.</div></div></div>${essayThemesHtml()}` }

// ---------- performance ----------
function performanceView(){const s=stats(),entries=Object.entries(s.topic).sort((a,b)=>b[1].done-a[1].done);return `<div class="page-head"><div><h1>Meu desempenho</h1><div class="muted">O objetivo é transferir o que aprendeu para fora da AEDS.</div></div><div class="seg no-print"><button id="shareWhats" class="btn btn-soft">Compartilhar WhatsApp</button><button id="pdfReport" class="btn btn-ghost">Relatório em PDF</button></div></div><div class="grid g4">${metric('Conhecimento',pct(s.knowledge)+'%')}${metric('Confiança',pct(s.confidence)+'%')}${metric('Velocidade',pct(s.speed)+'%')}${metric('Domínio agregado',pct(s.mastery)+'%','use a escada abaixo para domínio real')}</div>${masteryOverviewHtml()}<div class="grid g2" style="margin-top:14px"><div class="card"><h3>CDF</h3><p>Certeza: <b>${s.cdf.C}</b> · Dúvida: <b>${s.cdf.D}</b> · Falha: <b>${s.cdf.F}</b></p></div><div class="card"><h3>CID</h3><p>Conteúdo: <b>${s.cid.Conteudo}</b> · Interpretação: <b>${s.cid.Interpretacao}</b> · Distração: <b>${s.cid.Distracao}</b></p></div></div>${mathDiagnosisHtml()}${portDiagnosisHtml()}${generalSkillDiagnosisHtml()}<div class="card" style="margin-top:14px"><h3>Dificuldade por tópico</h3>${entries.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Tópico</th><th>Feitas</th><th>Domínio</th><th>Erros</th><th>Controle</th></tr></thead><tbody>${entries.map(([k,v])=>{const [sub,g,a]=k.split('|'),rate=v.done?Math.round(v.correct/v.done*100):0,setting=state.topicDifficulty[targetStudent().id][k]||'auto';return `<tr><td>${sub} · ${gradeName(g)} · ${a}</td><td>${v.done}</td><td>${rate}%</td><td>${v.errors}</td><td><select class="topicDiff" data-k="${esc(k)}"><option value="auto" ${setting==='auto'?'selected':''}>Automática</option>${['fácil','médio','difícil'].map(d=>`<option ${setting===d?'selected':''}>${d}</option>`).join('')}</select></td></tr>`}).join('')}</tbody></table></div>`:'<div class="notice">Responda questões para criar o mapa de domínio.</div>'}</div><div class="card" style="margin-top:14px"><h3>Histórico recente</h3><div class="list">${s.history.slice(-100).reverse().map(h=>{const q=qById(h.qid);return q?`<div class="item"><b>${q.subject} · ${q.area}</b> <span class="tag">${h.right?'correta':'erro'}</span> <span class="tag">CDF ${h.cdf}</span> <span class="tag">CID ${h.cid||'—'}</span><div class="tiny muted">${new Date(h.at).toLocaleString('pt-BR')}</div></div>`:''}).join('')||'<div class="muted">Sem histórico ainda.</div>'}</div></div>`}
function reportText(){const u=targetStudent(),s=stats(u.id);return `AEDS — A Evolução do Saber — Relatório de ${u.name}\nQuestões respondidas: ${s.questions}\nConhecimento: ${s.knowledge}%\nConfiança: ${s.confidence}%\nVelocidade: ${s.speed}%\nDomínio real: ${s.mastery}%\nCDF — Certeza ${s.cdf.C}, Dúvida ${s.cdf.D}, Falha ${s.cdf.F}\nCID — Conteúdo ${s.cid.Conteudo}, Interpretação ${s.cid.Interpretacao}, Distração ${s.cid.Distracao}`}

// ---------- favorites/formulas ----------
function favoritesView(){const ids=state.favorites[targetStudent().id],qs=ids.map(qById).filter(Boolean);return `<div class="page-head"><div><h1>Favoritos</h1><div class="muted">Questões salvas para consulta.</div></div></div><div class="list">${qs.map(q=>`<div class="item"><b>${q.subject} · ${q.area}</b><div>${esc(q.prompt.slice(0,200))}</div><button class="btn btn-danger removeFav" data-id="${q.id}">Remover</button></div>`).join('')||'<div class="notice">Nenhuma questão favorita.</div>'}</div>`}
function formulasView(){const u=targetStudent(),f=state.formulas[u.id];return `<div class="page-head"><div><h1>Banco de fórmulas pessoal</h1><div class="muted">Salve fórmulas, observações e lembretes próprios.</div></div></div><div class="grid g2"><div class="card"><div class="field"><label>Título</label><input id="formulaTitle" placeholder="Ex.: velocidade média"></div><div class="field"><label>Fórmula/observação</label><textarea id="formulaText" placeholder="v = Δs / Δt"></textarea></div><button id="addFormula" class="btn btn-primary">Salvar</button></div><div class="card"><h3>Minhas fórmulas</h3><div class="list">${f.map((x,i)=>`<div class="item"><b>${esc(x.title)}</b><pre style="white-space:pre-wrap">${esc(x.text)}</pre><button class="btn btn-danger delFormula" data-i="${i}">Excluir</button></div>`).join('')||'<div class="muted">Nenhuma fórmula salva.</div>'}</div></div></div>`}

// ---------- programming ----------
function programView(){const langs=Object.keys(PROGRAMMING);if(!langs.includes(ui.programLang))ui.programLang=langs[0];const c=PROGRAMMING[ui.programLang],lessons=c.lessons||[];if(ui.programLesson>=lessons.length)ui.programLesson=0;const l=lessons[ui.programLesson],done=state.programDone[targetStudent().id],key=`${ui.programLang}:${ui.programLesson}`;return `<div class="page-head"><div><h1>Programação</h1><div class="muted">Do conceito simples ao aprofundamento técnico, com laboratório prático.</div></div></div><div class="tabs">${langs.map(k=>`<button class="tab ${ui.programLang===k?'active':''}" data-lang="${k}">${esc(PROGRAMMING[k].title)}</button>`).join('')}</div><div class="course-layout"><aside class="card lesson-nav"><h3>${esc(c.title)}</h3><p class="muted small">${esc(c.description||'')}</p>${lessons.map((x,i)=>`<button class="lesson-btn ${i===ui.programLesson?'active':''}" data-lesson="${i}">${x.id?`<b>${esc(x.id)}</b> · `:''}${esc(x.title)} ${done.includes(`${ui.programLang}:${i}`)?'✓':''}</button>`).join('')}</aside><section class="grid"><article class="card article"><span class="pill">${esc(l.level||'Aula')}</span><h2>${l.id?esc(l.id)+' · ':''}${esc(l.title)}</h2><p>${esc(l.explanation||'')}</p>${l.formula?`<h3>Veja como fazer</h3><pre class="code">${esc(l.formula)}</pre>`:''}<h3>Passo a passo</h3><div class="steps">${(l.steps||[]).map(x=>`<div class="step">${esc(x)}</div>`).join('')}</div>${l.exampleTitle?`<h3>Exemplo resolvido · ${esc(l.exampleTitle)}</h3><div class="notice" style="white-space:pre-line">${esc(l.example)}</div>`:''}${l.example&&!l.exampleTitle?`<h3>Exemplo pronto</h3><pre class="code">${esc(l.example)}</pre>`:''}${l.lineByLine?`<h3>Linha por linha</h3><ul>${l.lineByLine.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${l.deep?`<details open><summary><b>Aprofundar: explicação técnica e fórmulas</b></summary><p>${esc(l.deep)}</p></details>`:''}${l.keep?`<div class="success"><b>Guarde esta ideia:</b> ${esc(l.keep)}</div>`:''}${l.interactive==='loop'?loopSimulator():''}</article>${['html','css','javascript','python','java','c','cpp','sql'].includes(ui.programLang)?labView(l,key):''}<div class="card"><button id="completeLesson" class="btn ${done.includes(key)?'btn-ok':'btn-primary'}">${done.includes(key)?'Aula concluída ✓':'Marcar aula concluída'}</button></div></section></div>`}
function loopSimulator(){return `<div class="card"><h3>Experimente · veja o algoritmo acontecer</h3><p>Condição: soma &lt; 6.</p><div id="loopState" class="notice">Etapa 0 · a = 0 · soma = 0</div><div class="seg"><button id="loopStep" class="btn btn-primary">Executar uma repetição</button><button id="loopReset" class="btn btn-ghost">Recomeçar</button></div></div>`}
function labView(l,key){const starter=l.starter||l.example||'';return `<div class="card"><h3>Laboratório prático</h3><div class="seg"><button id="loadStarter" class="btn btn-soft">Carregar exercício</button><button id="loadExample" class="btn btn-ghost">Carregar exemplo</button><button id="runCode" class="btn btn-primary">Executar/verificar</button></div><div class="grid g2" style="margin-top:10px"><textarea id="codeEditor" class="editor">${esc(starter)}</textarea><iframe id="codePreview" class="preview" sandbox="allow-scripts"></iframe></div><div id="codeStatus" class="notice">HTML/CSS/JavaScript executam no navegador; outras linguagens recebem verificação estrutural local.</div></div>`}
function runCode(){const lang=ui.programLang,l=PROGRAMMING[lang].lessons[ui.programLesson],code=$('#codeEditor')?.value||'',p=$('#codePreview'),stt=$('#codeStatus');if(lang==='html'){p.srcdoc=code;stt.textContent='Preview atualizado.';return}if(lang==='css'){p.srcdoc=`<style>${code.replace(/<\/style/gi,'<\\/style')}</style><h1>Preview CSS</h1><div class="card"><p>Texto de teste</p><button>Botão</button></div>`;stt.textContent='Preview CSS atualizado.';return}if(lang==='javascript'){const safe=code.replace(/<\/script/gi,'<\\/script');p.srcdoc=`<pre id=o></pre><script>const o=document.getElementById('o');console.log=(...a)=>o.textContent+=a.join(' ')+'\\n';try{${safe}}catch(e){o.textContent+=e}<\\/script>`;stt.textContent='JavaScript executado.';return}const miss=(l.checks||[]).filter(x=>!code.toLowerCase().includes(String(x).toLowerCase()));stt.textContent=miss.length?`Ainda falta demonstrar: ${miss.join(', ')}`:'Estrutura principal encontrada. Agora revise a lógica e teste outros casos.'}

// ---------- science/routine/sources/settings ----------
function scienceView(){return `<div class="page-head"><div><h1>Ciência da Computação & artigos científicos</h1><div class="muted">Leitura científica, método e avaliação de evidências.</div></div></div><div class="grid g2"><div class="card"><h3>Como ler um artigo</h3><div class="steps">${['Leia título, resumo e palavras-chave.','Identifique a pergunta ou hipótese.','Observe método, amostra e variáveis.','Analise resultados, gráficos e tabelas.','Leia limitações e conclusão.','Compare com outras fontes.'].map(x=>`<div class="step">${x}</div>`).join('')}</div></div><div class="card"><h3>Glossário</h3><p><b>Abstract:</b> resumo · <b>method:</b> método · <b>results:</b> resultados · <b>limitations:</b> limitações · <b>peer review:</b> revisão por pares · <b>preprint:</b> versão antes da revisão formal.</p></div></div><div class="card" style="margin-top:14px"><h3>Fontes científicas</h3>${refsHtml(['scielo','google_academico','nucleo_conhecimento','mit_ocw','openstax'])}</div>`}
function routineView(){const r=state.routine[targetStudent().id];return `<div class="page-head"><div><h1>Rotina</h1><div class="muted">Planejador opcional e flexível.</div></div></div><div class="card"><label class="choice"><input id="routineEnabled" type="checkbox" ${r.enabled?'checked':''}> Ativar planejador</label>${r.enabled?`<div class="field"><label>Meta semanal de questões</label><input id="weeklyGoal" type="number" value="${r.weeklyGoal}"></div><div class="field"><label>Compromisso/horário</label><input id="routineItem" placeholder="Escola, trabalho, academia, descanso..."></div><button id="addRoutine" class="btn btn-primary">Adicionar</button><div class="list" style="margin-top:10px">${r.items.map((x,i)=>`<div class="item">${esc(x)} <button class="btn btn-danger delRoutine" data-i="${i}">Excluir</button></div>`).join('')}</div>`:`<div class="notice">O planejador é opcional e pode ser ativado depois.</div>`}</div>`}
function sourcesView(){const cats=[...new Set(CREDITS.map(c=>c.category))];return `<div class="page-head"><div><h1>Fontes e créditos</h1><div class="muted">Questões próprias registram referências; questões oficiais ficam separadas.</div></div></div><div class="notice"><b>Política:</b> questões autorais da AEDS usam as fontes para conferir conteúdo e abordagem, sem copiar exercícios literalmente. Wikipédia é complementar, não fonte única para conteúdo importante. ENEM, OBMEP e vestibulares ficam no banco oficial com prova, ano e origem.</div>${cats.map(cat=>`<h3>${esc(cat)}</h3><div class="source-grid">${CREDITS.filter(c=>c.category===cat).map(c=>`<div class="source"><a href="${esc(c.url)}" target="_blank" rel="noopener">${esc(c.name)}</a><div class="muted small">${esc(c.category)}</div><div class="tiny">${(c.questionReferences||0).toLocaleString('pt-BR')} associações no banco-base</div></div>`).join('')}</div>`).join('')}<div class="card" style="margin-top:14px"><h3>Banco oficial separado</h3><p>A AEDS mantém metadados de questões oficiais separados das questões próprias. Use a importação administrativa para registrar prova, ano, origem e banca.</p><div class="refs"><a class="ref" href="https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos" target="_blank">ENEM / INEP</a><a class="ref" href="https://www.obmep.org.br/provas.htm" target="_blank">OBMEP</a><a class="ref" href="https://www.fuvest.br/vestibular-da-usp/" target="_blank">FUVEST</a><a class="ref" href="https://www.comvest.unicamp.br/vestibulares-anteriores/" target="_blank">UNICAMP / COMVEST</a></div></div>`}
function officialView(){const qs=state.officialQuestions;const exams=[...new Set(qs.map(q=>q.exam||q.sourceTitle||'Sem prova'))];return `<div class="page-head"><div><h1>Banco oficial</h1><div class="muted">Separado das questões próprias. Cada item deve informar prova, ano e origem.</div></div></div><div class="notice">Para respeitar a origem dos materiais, o banco oficial só contém questões que o administrador importar ou registrar com metadados. As questões autorais referenciadas ficam no banco principal.</div><div class="toolbar"><div class="field"><label>Prova/banca</label><select id="officialExam"><option value="">Todas</option>${exams.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><div class="field"><label>Ano</label><input id="officialYear" placeholder="Ex.: 2025"></div></div><div class="card" style="margin-top:12px"><div id="officialList" class="list">${officialListHtml(qs)}</div></div>`}
function officialListHtml(qs){return qs.length?qs.slice(0,300).map(q=>`<div class="item"><b>${esc(q.exam||q.sourceTitle||'Questão oficial')}</b> <span class="tag">${esc(q.year||'ano não informado')}</span><div>${esc(q.prompt.slice(0,220))}</div><div class="tiny muted">${esc(q.subject)} · ${esc(q.area)} · origem: ${esc(q.sourceTitle||q.origin?.note||'não informada')}</div></div>`).join(''):'<div class="notice">Nenhuma questão oficial importada ainda. Use o painel Admin → Importar questões e marque source_type=official.</div>'}
function settingsView(){return `<div class="page-head"><div><h1>Configurações</h1></div></div><div class="grid g2"><div class="card"><h3>Aparência</h3><div class="seg"><button id="themeToggle" class="btn btn-ghost">Claro/escuro</button>${[[.9,'A−'],[1,'A'],[1.15,'A+']].map(x=>`<button class="btn btn-ghost fontScale" data-v="${x[0]}">${x[1]}</button>`).join('')}</div></div><div class="card"><h3>Backup pessoal</h3><button id="exportBackup" class="btn btn-primary">Exportar backup JSON</button><div class="field"><label>Restaurar backup</label><input id="importBackup" type="file" accept=".json"></div></div></div><div class="card" style="margin-top:14px"><h3>Modo de dados</h3><p>${CLOUD.enabled?'Nuvem habilitada: progresso sincronizável entre dispositivos.':'Local: progresso salvo neste navegador. O pacote cloud/ contém a estrutura para Supabase e publicação.'}</p></div><div class="card" style="margin-top:14px"><h3>Atalhos de teclado</h3><p>Treinamento: <b>1–6</b> escolhem alternativa, <b>C/D/F</b> CDF, <b>H</b> dica, <b>N</b> próxima questão, <b>R</b> foca no rascunho.</p></div>`}

// ---------- admin ----------
function mathCoverageHtml(){const qs=candidateBank().filter(q=>q.subject==='Matemática'&&q.questionType==='multiple_choice'),rows=[5,6,7,8,9,10,11,12].map(g=>{const sub=qs.filter(q=>Number(q.grade)===g),roots=new Set(sub.map(q=>q.rootFamily||q.family||q.id)),patterns=new Set(sub.map(q=>promptPattern(q))),skillRows=[];for(const u of mathUnits(g))for(const sk of u.skills){const items=sub.filter(q=>q.area===u.unit&&q.skill===sk),rr=new Set(items.map(q=>q.rootFamily||q.family||q.id));skillRows.push({unit:u.unit,skill:sk,count:items.length,roots:rr.size})}return {g,count:sub.length,roots:roots.size,patterns:patterns.size,low:skillRows.filter(x=>x.roots<3)}});const low=rows.flatMap(r=>r.low.map(x=>({...x,g:r.g})));return `<div class="card" style="margin-top:14px"><div class="page-head" style="margin-bottom:10px"><div><h3 style="margin:0">Auditoria de Matemática 9.0</h3><div class="muted small">A cobertura real considera famílias semânticas, não apenas o número bruto de variações.</div></div><span class="pill">${qs.length.toLocaleString('pt-BR')} questões</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Série</th><th>Questões</th><th>Famílias semânticas</th><th>Padrões estruturais</th><th>Habilidades com &lt;3 famílias</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${gradeName(r.g)}</td><td>${r.count}</td><td><b>${r.roots}</b></td><td>${r.patterns}</td><td>${r.low.length}</td></tr>`).join('')}</tbody></table></div>${low.length?`<details style="margin-top:10px"><summary class="btn btn-ghost">Ver lacunas prioritárias (${low.length})</summary><div class="list" style="margin-top:10px">${low.slice(0,60).map(x=>`<div class="item"><b>${gradeName(x.g)} · ${esc(x.skill)}</b><div class="tiny muted">${esc(x.unit)} · ${x.count} questões · ${x.roots} famílias realmente diferentes</div></div>`).join('')}</div></details>`:`<div class="success">Todas as micro-habilidades têm ao menos três famílias semânticas.</div>`}</div>`}
function portCoverageHtml(){const qs=candidateBank().filter(q=>q.subject==='Português'&&q.questionType==='multiple_choice'),legacy=BANK.filter(q=>q.subject==='Português'&&q.active===false).length,rows=[5,6,7,8,9,10,11,12].map(g=>{const sub=qs.filter(q=>Number(q.grade)===g),roots=new Set(sub.map(q=>q.rootFamily||q.family||q.id)),patterns=new Set(sub.map(q=>promptPattern(q))),skillRows=[];for(const u of portUnits(g))for(const sk of u.skills){const items=sub.filter(q=>q.area===u.unit&&q.skill===sk),rr=new Set(items.map(q=>q.rootFamily||q.family||q.id));skillRows.push({unit:u.unit,skill:sk,count:items.length,roots:rr.size})}return {g,count:sub.length,roots:roots.size,patterns:patterns.size,low:skillRows.filter(x=>x.roots<3)}});const low=rows.flatMap(r=>r.low.map(x=>({...x,g:r.g})));return `<div class="card" style="margin-top:14px"><div class="page-head" style="margin-bottom:10px"><div><h3 style="margin:0">Auditoria de Português 9.0</h3><div class="muted small">Questões antigas genéricas ficam preservadas para histórico, mas não entram no treino normal. Cobertura real = famílias ativas e micro-habilidades.</div></div><span class="pill">${qs.length.toLocaleString('pt-BR')} objetivas ativas</span></div><div class="notice"><b>${legacy.toLocaleString('pt-BR')}</b> questões antigas de Português estão em quarentena para não contaminar o treino com moldes genéricos.</div><div class="table-wrap" style="margin-top:10px"><table class="table"><thead><tr><th>Série</th><th>Questões</th><th>Famílias</th><th>Padrões</th><th>Habilidades com &lt;3 famílias</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${gradeName(r.g)}</td><td>${r.count}</td><td><b>${r.roots}</b></td><td>${r.patterns}</td><td>${r.low.length}</td></tr>`).join('')}</tbody></table></div>${low.length?`<details style="margin-top:10px"><summary class="btn btn-ghost">Ver lacunas reais (${low.length})</summary><div class="list" style="margin-top:10px">${low.slice(0,80).map(x=>`<div class="item"><b>${gradeName(x.g)} · ${esc(x.skill)}</b><div class="tiny muted">${esc(x.unit)} · ${x.count} questões · ${x.roots} famílias realmente diferentes</div></div>`).join('')}</div></details>`:`<div class="success">Todas as micro-habilidades têm ao menos três famílias.</div>`}</div>`}

function adminView(){const students=state.users.filter(u=>u.role==='student');return `<div class="page-head"><div><h1>Painel do administrador</h1><div class="muted">Usuários, permissões, banco, correções e histórico sem editar o banco manualmente.</div></div></div><div class="grid g4">${metric('Questões',MANIFEST.totalQuestions.toLocaleString('pt-BR'))}${metric('Alunos',students.length)}${metric('Correções pendentes',state.manualQueue.filter(x=>x.status==='pending').length)}${metric('Feedbacks',state.feedback.length)}</div>${mathCoverageHtml()}${portCoverageHtml()}${feedbackAdminHtml()}<div class="grid g2" style="margin-top:14px"><div class="card"><h3>Criar aluno</h3><div class="field"><label>Nome</label><input id="newName"></div><div class="field"><label>Usuário</label><input id="newUsername"></div><div class="field"><label>Senha</label><input id="newPassword" value="1234"></div><div class="field"><label>Série inicial</label><select id="newGrade">${[5,6,7,8,9,10,11,12].map(g=>`<option value="${g}">${gradeName(g)}</option>`).join('')}</select></div><button id="createUser" class="btn btn-primary">Criar usuário</button></div><div class="card"><h3>Importar questões</h3><p class="small">CSV funciona offline. XLSX é aceito quando a biblioteca de planilha puder ser carregada pela internet.</p><div class="field"><label>Arquivo CSV/XLSX</label><input id="questionFile" type="file" accept=".csv,.xlsx,.xls"></div><div class="seg"><button id="importQuestions" class="btn btn-primary">Importar</button><button id="runDuplicates" class="btn btn-soft">Detector de duplicatas</button></div><div id="importStatus" class="notice hidden"></div><p class="tiny muted">Colunas: id, subject, grade, area, skill, difficulty, type, prompt, A, B, C, D, E, F, correct, explanation, source_type, source_title, year, origin.</p></div></div><div class="card" style="margin-top:14px"><div class="page-head" style="margin-bottom:10px"><div><h3 style="margin:0">Usuários</h3><div class="muted small">As permissões abaixo são salvas no Supabase.</div></div><button id="refreshStudents" class="btn btn-ghost">Recarregar alunos</button></div><div class="list">${students.length?students.map(u=>userAdminCard(u)).join(''):'<div class="notice">Nenhum aluno cadastrado ainda. Crie uma conta em Supabase → Authentication → Users → Add user → Create new user e depois clique em <b>Recarregar alunos</b>.</div>'}</div></div><div class="grid g2" style="margin-top:14px"><div class="card"><h3>Correção manual</h3>${manualQueueHtml()}</div><div class="card"><h3>Histórico de mudanças</h3><div class="list audit">${state.audit.slice(-100).reverse().map(a=>`<div class="item">${new Date(a.at).toLocaleString('pt-BR')} · <b>${esc(a.user)}</b> · ${esc(a.action)} · ${esc(a.detail)}</div>`).join('')||'<div class="muted">Nenhuma mudança ainda.</div>'}</div></div></div><div class="card" style="margin-top:14px"><h3>Dados e qualidade</h3><p class="small">Exporte respostas anonimizadas por ID interno para futura calibração estatística dos itens da TRI-AEDS.</p><div class="seg"><button id="adminBackup" class="btn btn-primary">Exportar backup</button><button id="exportTriCalibration" class="btn btn-soft">Exportar dados TRI (CSV)</button><button id="clearDemo" class="btn btn-danger">Zerar dados dos alunos</button></div></div>`}
function userAdminCard(u){const subs=Object.keys(MANIFEST.subjects);return `<div class="item"><div style="display:flex;justify-content:space-between;gap:10px"><div><b>${esc(u.name)}</b> <span class="tag">${esc(u.username)}</span> ${u.blocked?'<span class="tag" style="color:var(--bad)">bloqueado</span>':''}<div class="muted small">${gradeName(u.grade)} · ${stats(u.id).questions} questões feitas</div></div><div class="seg"><button class="btn btn-soft editUser" data-id="${u.id}">Editar</button><button class="btn ${u.blocked?'btn-ok':'btn-danger'} blockUser" data-id="${u.id}">${u.blocked?'Desbloquear':'Bloquear'}</button></div></div><div style="margin-top:10px"><b class="small">Séries liberadas</b><div class="seg">${[5,6,7,8,9,10,11,12].map(g=>`<label class="choice"><input class="unlockGrade" data-id="${u.id}" value="${g}" type="checkbox" ${u.unlockedGrades.includes(g)?'checked':''}> ${gradeName(g)}</label>`).join('')}</div></div><div style="margin-top:10px"><b class="small">Matérias liberadas</b><div class="seg">${subs.map(s=>`<label class="choice"><input class="unlockSubject" data-id="${u.id}" value="${esc(s)}" type="checkbox" ${u.unlockedSubjects.includes(s)?'checked':''}> ${esc(s)}</label>`).join('')}</div></div><label class="choice" style="margin-top:8px"><input class="unlockExam" data-id="${u.id}" type="checkbox" ${u.examsUnlocked?'checked':''}> Provas liberadas</label></div>`}
function manualQueueHtml(){const pending=state.manualQueue.filter(x=>x.status==='pending');return pending.length?`<div class="list">${pending.slice(0,30).map(x=>`<div class="item"><b>${esc(x.kind)} · ${esc(x.studentName)}</b><div class="small">${esc(x.prompt)}</div><details><summary>Resposta</summary><p style="white-space:pre-wrap">${esc(x.answer)}</p></details><div class="field"><label>Nota (0–1000 ou 0–100)</label><input class="manualScore" data-id="${x.id}" type="number"></div><div class="field"><label>Comentário</label><textarea class="manualComment" data-id="${x.id}"></textarea></div><button class="btn btn-ok gradeManual" data-id="${x.id}">Salvar correção</button></div>`).join('')}</div>`:'<div class="notice">Nenhuma correção pendente.</div>'}

// ---------- global search ----------
function runSearch(q){q=q.trim().toLowerCase();if(q.length<2)return[];const res=[];for(const [s,v] of Object.entries(MANIFEST.subjects)){if(s.toLowerCase().includes(q))res.push({type:'Matéria',title:s,sub:`${v.total} questões`,action:{page:'learn',subject:s}});for(const [g,gradeMeta] of Object.entries(v.grades)){const areas=gradeMeta?.areas&&typeof gradeMeta.areas==='object'?gradeMeta.areas:gradeMeta;for(const a of Object.keys(areas||{}))if(a.toLowerCase().includes(q))res.push({type:'Conteúdo',title:a,sub:`${s} · ${gradeName(g)}`,action:{page:'learn',subject:s,grade:Number(g),area:a}})}}for(const [g,units] of Object.entries(MATH_CURRICULUM))for(const unit of units)for(const sk of unit.skills)if((sk+' '+unit.unit).toLowerCase().includes(q))res.push({type:'Habilidade matemática',title:sk,sub:`Matemática · ${gradeName(g)} · ${unit.unit}`,action:{page:'train',subject:'Matemática',grade:Number(g),area:unit.unit,skill:sk}});for(const [g,units] of Object.entries(PORT_CURRICULUM))for(const unit of units)for(const sk of unit.skills)if((sk+' '+unit.unit).toLowerCase().includes(q))res.push({type:'Habilidade de Português',title:sk,sub:`Português · ${gradeName(g)} · ${unit.unit}`,action:{page:'train',subject:'Português',grade:Number(g),area:unit.unit,skill:sk}});for(const [sub,grades] of Object.entries(FOCUS_CURRICULUM))for(const [g,units] of Object.entries(grades))for(const unit of units)for(const sk of unit.skills||[])if((sk+' '+unit.unit+' '+sub).toLowerCase().includes(q))res.push({type:'Aprofundamento ENEM',title:sk,sub:`${sub} · ${gradeName(g)} · ${unit.unit}`,action:{page:'learn',subject:sub,grade:Number(g),area:unit.unit}});const rep=ESSAY_REPERTOIRE?.brasil_pais_do_futuro;if(rep&&(rep.title+' '+rep.author+' '+(rep.axes||[]).map(x=>x.axis).join(' ')).toLowerCase().includes(q))res.push({type:'Repertório de redação',title:rep.title,sub:`${rep.author} · guia crítico para o ENEM`,action:{page:'essay'}});for(const [k,c] of Object.entries(PROGRAMMING))for(let i=0;i<(c.lessons||[]).length;i++){const l=c.lessons[i];if((l.title+' '+(l.explanation||'')).toLowerCase().includes(q))res.push({type:'Programação',title:l.title,sub:c.title,action:{page:'program',lang:k,lesson:i}})}for(const t of ESSAY_THEMES)if((t.title+' '+t.axis).toLowerCase().includes(q))res.push({type:'Tema de redação',title:t.title,sub:t.axis,action:{page:'essay',essayPrompt:t.title}});for(const c of CREDITS)if((c.name+' '+c.category).toLowerCase().includes(q))res.push({type:'Fonte',title:c.name,sub:c.category,url:c.url});return res.slice(0,35)}
function showSearch(){const box=$('#searchResults');if(!box)return;const res=runSearch(ui.search);box.innerHTML=res.length?res.map((r,i)=>`<button class="search-result" data-search-i="${i}"><b>${esc(r.title)}</b><div class="tiny muted">${esc(r.type)} · ${esc(r.sub)}</div></button>`).join(''):'<div class="muted small" style="padding:9px">Nenhum resultado.</div>';box.classList.remove('hidden');box._results=res}

// ---------- import/duplicates ----------
function normalizePrompt(s){return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\b\d+(?:[.,]\d+)?%?\b/g,'<n>').replace(/\s+/g,' ').trim()}
function duplicateReport(rows=candidateBank()){const seen=new Map(),exact=[],near=[],sameRoot=[],samePattern=[];for(const q of rows){const ex=String(q.prompt).trim().toLowerCase(),sem=`${q.subject}|${q.grade}|${q.area}|${normalizePrompt(q.prompt)}`,root=q.rootFamily||q.family,pat=promptPattern(q);if(seen.has('e:'+ex))exact.push([seen.get('e:'+ex),q]);else seen.set('e:'+ex,q);if(seen.has('s:'+sem))near.push([seen.get('s:'+sem),q]);else seen.set('s:'+sem,q);if(root){if(seen.has('r:'+root))sameRoot.push([seen.get('r:'+root),q]);else seen.set('r:'+root,q)}if(pat){if(seen.has('p:'+pat))samePattern.push([seen.get('p:'+pat),q]);else seen.set('p:'+pat,q)}}return {exact,near,sameRoot,samePattern}}
function parseCSV(text){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean),rows=[];if(!lines.length)return rows;const parse=line=>{const a=[];let cur='',quote=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(quote&&line[i+1]==='"'){cur+='"';i++}else quote=!quote}else if(c===','&&!quote){a.push(cur);cur=''}else cur+=c}a.push(cur);return a};const head=parse(lines[0]).map(x=>x.trim());for(const line of lines.slice(1)){const vals=parse(line),o={};head.forEach((h,i)=>o[h]=vals[i]??'');rows.push(o)}return rows}
function importedQuestion(r,i,official=false){const opts=['A','B','C','D','E','F'].map(k=>r[k]??r[k.toLowerCase()]??'').filter(x=>String(x).trim()!==''),ci=['A','B','C','D','E','F'].indexOf(String(r.correct||'').trim().toUpperCase());return {id:r.id||`${official?'OFF':'CUS'}-${Date.now()}-${i}`,subject:r.subject||'Matemática',grade:Number(r.grade)||5,area:r.area||r.topic||'Importado',skill:r.skill||r.area||'Importado',difficulty:r.difficulty||'médio',type:r.type||'conteúdo',questionType:r.questionType||'multiple_choice',prompt:r.prompt||'',hint:r.hint||'',options:opts,correctIndex:ci,correctText:opts[ci]||'',explanation:r.explanation||'',explanationSteps:['Leia o comando.','Identifique o conteúdo.','Resolva.','Confira.'],optionExplanations:opts.map((o,j)=>j===ci?'Correta conforme o gabarito importado.':`Incorreta. Confira a explicação e a fonte.`),references:[],origin:{type:official?'official':'imported',label:official?'Questão oficial importada':'Questão importada',note:r.source_title||r.origin||''},family:`import:${normalizePrompt(r.prompt)}:${r.skill||''}`,rootFamily:`import:${normalizePrompt(r.prompt)}`,calculatorAllowed:false,prerequisite:'',media:null,year:r.year||'',exam:r.exam||r.source_title||'',sourceTitle:r.source_title||'',n:null,version:9}}
async function readQuestionFile(file){if(file.name.toLowerCase().endsWith('.csv'))return parseCSV(await file.text());if(/\.xlsx?$/.test(file.name.toLowerCase())){if(!window.XLSX){await loadScript('https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js').catch(()=>{});}if(!window.XLSX)throw new Error('Sem internet para carregar o leitor XLSX. Salve a planilha como CSV e importe novamente.');const buf=await file.arrayBuffer(),wb=XLSX.read(buf),ws=wb.Sheets[wb.SheetNames[0]];return XLSX.utils.sheet_to_json(ws,{defval:''})}throw new Error('Formato não suportado.')}
function loadScript(src){return new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=reject;document.head.appendChild(s)})}

// ---------- utility downloads ----------
function download(name,text,type='application/json'){const b=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}

// ---------- render ----------
function render(){document.documentElement.style.fontSize=`${16*(state?.settings?.fontScale||1)}px`;document.body.classList.toggle('dark',state?.settings?.theme==='dark');document.body.classList.toggle('focus-mode',ui.focus);if(!state.currentUser||!me()){APP.innerHTML=loginView();wireLogin();return}const fn={home,admin:adminView,learn:learnView,train:trainView,exam:examView,review:reviewView,essay:essayView,performance:performanceView,favorites:favoritesView,formulas:formulasView,program:programView,science:scienceView,routine:routineView,sources:sourcesView,official:officialView,settings:settingsView}[ui.page]||home;APP.innerHTML=shell(fn());wire();if(ui.page==='exam'&&ui.exam&&!ui.exam.finished)startExamTimer();if(ui.page==='essay')startEssayTimer()}

