const AEDS903_ICON_MAP={home:'home',learn:'learn',train:'train',exam:'exam',review:'review',essay:'essay',performance:'performance',favorites:'favorites',formulas:'formulas',program:'program',science:'science',routine:'routine',sources:'sources',official:'official',settings:'settings',admin:'admin'};
function aedsIcon(name,size=20){const p=AEDS903_ICONS[name]||AEDS903_ICONS.home;return `<svg class="ui-icon" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p}</svg>`}
function navIcon(page,size=20){return aedsIcon(AEDS903_ICON_MAP[page]||page,size)}

subjectIcon=function(s){const map={'Matemática':'M','Português':'PT','Ciências':'C','História':'H','Geografia':'G','Inglês':'EN','Redação':'R','Artes':'A','Educação Física':'EF','Educação Financeira':'$','Computação':'CS','Espanhol':'ES','Projeto de Vida':'PV','Metodologia Científica':'MC','Robótica':'RB','Física':'F','Química':'Q','Biologia':'B','Literatura':'L','Filosofia':'FI','Sociologia':'SO'};return map[s]||String(s||'').slice(0,2).toUpperCase()}
visualAction=function(page,icon,label,sub,tone='red'){return `<button class="visual-action tone-${tone}" data-page="${page}" aria-label="${esc(label)}"><span class="visual-action-icon" aria-hidden="true">${navIcon(page,22)}</span><span class="visual-action-copy"><b>${esc(label)}</b><small>${esc(sub)}</small></span><span class="visual-action-arrow" aria-hidden="true">${aedsIcon('arrow',18)}</span></button>`}

loginView=function(){return `<div class="login clean-login"><div class="login-card clean-login-card"><section class="login-hero clean-login-hero"><div class="brand-lockup"><div class="brand-mark">A</div><div><b>AEDS</b><span>A Evolução do Saber</span></div></div><div class="login-pitch"><span class="eyebrow">ESTUDO ADAPTATIVO</span><h1>Aprenda melhor.<br>Não por mais tempo.</h1><p>Entenda, pratique e descubra exatamente o que precisa revisar.</p></div><div class="login-trust"><span>Sem anúncios</span><span>Sem gamificação artificial</span><span>Foco em autonomia</span></div></section><section class="login-form clean-login-form"><div><span class="eyebrow">BEM-VINDO</span><h2>Entrar na AEDS</h2><p class="muted">Continue de onde parou.</p></div><div class="field"><label>${CLOUD.enabled?'E-mail':'Usuário'}</label><input id="loginUser" type="${CLOUD.enabled?'email':'text'}" autocomplete="username" placeholder="${CLOUD.enabled?'seuemail@exemplo.com':''}"></div><div class="field"><label>Senha</label><input id="loginPass" type="password" autocomplete="current-password"></div><button id="loginBtn" class="btn btn-primary btn-big" style="width:100%">Entrar</button><div id="loginErr" class="danger hidden"></div>${CLOUD.enabled?'':`<div class="notice"><b>Teste local:</b> admin / 1234 · aluno / 1234</div>`}</section></div></div>`}

sidebar=function(){const m=me(),coreKeys=['home','learn','train','exam','review','performance'];const all=m.role==='admin'?[['admin','','Admin'],...NAV]:NAV;const core=all.filter(x=>coreKeys.includes(x[0])||(m.role==='admin'&&x[0]==='admin'));const resources=all.filter(x=>!core.some(c=>c[0]===x[0]));const moreActive=resources.some(x=>x[0]===ui.page);const renderNav=x=>`<button class="nav ${ui.page===x[0]?'active':''}" data-page="${x[0]}" aria-label="${x[2]}"><span class="ico">${navIcon(x[0],19)}</span><span class="label">${x[2]}</span></button>`;return `<aside class="sidebar clean-sidebar"><div class="brand"><div class="brand-mark">A</div><div><h2>AEDS</h2><div class="muted tiny">A Evolução do Saber</div></div></div><div class="desktop-nav clean-desktop-nav">${core.map(renderNav).join('')}<details class="resource-nav" ${moreActive?'open':''}><summary>${aedsIcon('menu',18)}<span>Recursos</span></summary><div class="resource-nav-list">${resources.map(renderNav).join('')}</div></details><div class="sidebar-spacer"></div><button class="nav" id="logout"><span class="ico">${aedsIcon('logout',19)}</span><span class="label">Sair</span></button></div><div class="mobile-nav clean-mobile-nav">${core.filter(x=>['home','learn','train','exam'].includes(x[0])).map(renderNav).join('')}<details class="mobile-more"><summary class="nav ${moreActive||ui.page==='review'||ui.page==='performance'?'active':''}"><span class="ico">${aedsIcon('menu',20)}</span><span class="label">Mais</span></summary><div class="mobile-more-sheet"><div class="mobile-more-head"><div><b>Menu</b><div class="tiny muted">Todos os recursos</div></div><button type="button" class="mobile-more-close" id="mobileMoreClose" aria-label="Fechar menu">×</button></div><div class="mobile-more-grid clean-more-list">${all.filter(x=>!['home','learn','train','exam'].includes(x[0])).map(x=>`<button class="mobile-more-item ${ui.page===x[0]?'active':''}" data-page="${x[0]}"><span class="ico">${navIcon(x[0],19)}</span><span>${x[2]}</span></button>`).join('')}<button class="mobile-more-item danger-link" id="mobileLogout"><span class="ico">${aedsIcon('logout',19)}</span><span>Sair</span></button></div></div></details></div></aside>`}

shell=function(body){const m=me(),label=PAGE_VISUAL[ui.page]?.label||'AEDS';return `<a class="skip-link" href="#mainContent">Pular para o conteúdo</a><div class="shell">${sidebar()}<main class="main"><header class="topbar clean-topbar"><div class="page-identity"><span>${navIcon(ui.page,18)}</span><b>${esc(label)}</b></div><div class="searchbox clean-search"><span class="search-icon">${aedsIcon('search',18)}</span><input id="globalSearch" value="${esc(ui.search)}" placeholder="Buscar conteúdo"><div id="searchResults" class="search-results ${ui.searchOpen?'':'hidden'}"></div></div><div class="top-actions"><button id="speakPage" class="icon-btn no-print" title="Ouvir esta tela" aria-label="Ouvir esta tela">${aedsIcon('volume',19)}</button><button id="focusBtn" class="icon-btn no-print" title="Modo foco" aria-label="Modo foco">${aedsIcon('focus',19)}</button><div class="user-chip"><div class="avatar">${esc(m.name[0])}</div><div class="user-text"><b class="small">${esc(m.name)}</b><div class="tiny muted">${m.role==='admin'?'Administrador':gradeName(m.grade)}</div></div></div></div></header><section class="content" id="mainContent" tabindex="-1">${body}<div class="footer">AEDS · V9.0.13 · ${CLOUD.enabled?'nuvem ativa':'modo local'}</div><div id="ariaLive" class="sr-only" aria-live="polite"></div></section></main></div>`}

pageSpeech=function(){const phrases={home:'Você está no início. Escolha continuar estudando, aprender um conteúdo, treinar ou fazer um simulado.',learn:'Você está em Aprender. Escolha uma matéria, depois a série e o assunto.',train:'Você está em Treinar. Comece uma sessão inteligente ou escolha o conteúdo.',exam:'Você está em Provas. Escolha o dia do simulado.',review:'Você está em Revisar. Aqui ficam conhecimentos que precisam de outra tentativa.',performance:'Você está em Progresso. Aqui você acompanha o que já consegue fazer sem ajuda.'};return phrases[ui.page]||`Você está em ${PAGE_VISUAL[ui.page]?.label||'AEDS'}.`}

function aeds903Recommendation(){const r=AEDS_ANALYTICS.todayRecommendation(stats(),candidateBank(),qById);return `<section class="home-recommendation"><div><span class="eyebrow">PRÓXIMO PASSO</span><h2>${esc(r.title)}</h2><p>${esc(r.text)}</p></div><button class="btn btn-primary" data-page="${r.page}">Continuar ${aedsIcon('arrow',17)}</button></section>`}
home=function(){const m=me();if(m.role==='admin')return adminHome();const s=stats(),first=esc((m.name||'Aluno').split(/\s+/)[0]),due=dueSkillKeys(m.id).length,independent=Object.keys(s.skill).filter(k=>stageForSkillKey(k,m.id).level===4).length;return `<div class="student-home clean-home"><section class="home-intro"><div><span class="eyebrow">AEDS</span><h1>Olá, ${first}.</h1><p>Um passo de cada vez. A plataforma escolhe o que merece sua atenção agora.</p></div><div class="home-status"><b>${due}</b><span>revisões hoje</span></div></section>${aeds903Recommendation()}<section class="clean-primary-actions">${visualAction('learn','', 'Aprender','Entender um conteúdo','blue')}${visualAction('train','', 'Treinar','Praticar sem repetição','red')}${visualAction('exam','', 'Simulado','Testar o que você sabe','purple')}</section><details class="home-more"><summary>Mais recursos</summary><div class="home-resource-links"><button data-page="review">Revisões</button><button data-page="performance">Progresso</button><button data-page="essay">Redação</button><button data-page="program">Computação</button><button data-page="favorites">Favoritos</button><button data-page="settings">Configurações</button></div></details><section class="home-quiet-progress"><div><span>Independentes</span><b>${independent}</b></div><div><span>Questões feitas</span><b>${s.questions.toLocaleString('pt-BR')}</b></div><button class="text-link" data-page="performance">Ver progresso completo</button></section></div>`}

todayCard=aeds903Recommendation;


// ---------- keyboard ----------
document.addEventListener('keydown',e=>{if(!me()||ui.page!=='train'||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if(/^[1-6]$/.test(e.key)&&!ui.corrected)selectAnswer(Number(e.key)-1);else if(['c','d','f'].includes(e.key.toLowerCase())&&!ui.corrected)setCDF(e.key.toUpperCase());else if(e.key.toLowerCase()==='h')$('#hintBtn')?.click();else if(e.key.toLowerCase()==='n'&&ui.corrected)$('#nextQ')?.click();else if(e.key.toLowerCase()==='r')$('#scratch')?.focus()});


// ---------- AEDS 9.0.6 · Ciência da Computação autoral ----------
const AEDS906_PROGRAM_VIEW=programView;
const AEDS906_RUN_SEARCH=runSearch;
const AEDS906_WIRE=wire;

function csBook(){return window.AEDS_CS_FOUNDATIONS||null}
function csDoneKey(kind,id){return `cs:${kind}:${id}`}
function csIsDone(kind,id){return (state.programDone[targetStudent().id]||[]).includes(csDoneKey(kind,id))}
function csToggleDone(kind,id){const a=state.programDone[targetStudent().id],k=csDoneKey(kind,id),i=a.indexOf(k);if(i>=0)a.splice(i,1);else a.push(k);localSave()}
function csNote(kind,id){const uid=targetStudent().id,key=`cs-work:${kind}:${id}`;state.notes[uid]=state.notes[uid]||{};state.notes[uid][key]=state.notes[uid][key]||{hypothesis:'',evidence:'',explanation:'',nextTest:'',transfer:'',updatedAt:null};return state.notes[uid][key]}
function csProgress(){const d=csBook();if(!d)return{modules:0,projects:0};return{modules:d.modules.filter(m=>csIsDone('module',m.id)).length,projects:d.projects.filter(p=>csIsDone('project',p.id)).length}}
function csModeSwitch(){const foundation=ui.programLang==='fundamentos_cs';return `<div class="cs-mode-switch" role="tablist" aria-label="Modo de estudo de computação"><button class="${foundation?'active':''}" data-cs-mode="fundamentos">Fundamentos</button><button class="${!foundation?'active':''}" data-cs-mode="linguagens">Linguagens</button></div>`}
function csTabs(){const t=ui.csTab||'trilha',tabs=[['trilha','Trilha'],['casos','Casos'],['laboratorio','Laboratório'],['projetos','Projetos'],['glossario','Glossário'],['livro','Livro completo']];return `<nav class="cs-tabs" aria-label="Seções de Ciência da Computação">${tabs.map(([k,l])=>`<button class="${t===k?'active':''}" data-cs-tab="${k}">${l}</button>`).join('')}</nav>`}
function csCycleHtml(){const d=csBook();return `<div class="cs-cycle">${d.masteryCycle.map((x,i)=>`<div><span>${i+1}</span><b>${esc(x)}</b></div>`).join('')}</div>`}
function csModuleNav(d){const done=state.programDone[targetStudent().id]||[];return `<aside class="card cs-module-nav"><div class="eyebrow">TRILHA</div><h3>${esc(d.title)}</h3><p class="muted small">A ordem foi desenhada para criar dependências progressivas.</p>${d.modules.map((m,i)=>`<button class="cs-module-link ${i===ui.programLesson?'active':''}" data-cs-module="${i}"><span>${String(i+1).padStart(2,'0')}</span><div><b>${esc(m.title.replace(/^\d+\.\s*/,''))}</b><small>${done.includes(csDoneKey('module',m.id))?'Concluído':'Em estudo'}</small></div></button>`).join('')}</aside>`}
function csModuleArticle(d){if(ui.programLesson>=d.modules.length||ui.programLesson<0)ui.programLesson=0;const m=d.modules[ui.programLesson],n=csNote('module',m.id),done=csIsDone('module',m.id);return `<section class="cs-module-content"><article class="card article cs-lesson"><div class="cs-lesson-head"><div><span class="eyebrow">MÓDULO ${ui.programLesson+1} DE ${d.modules.length}</span><h2>${esc(m.title)}</h2><p>${esc(m.subtitle)}</p></div><span class="cs-status ${done?'done':''}">${done?'Concluído':'Em estudo'}</span></div><div class="cs-source-box"><b>Ideia central do seu livro</b><p>${esc(m.source)}</p></div><h3>Conceitos e mecanismos</h3><div class="cs-concepts">${m.concepts.map(c=>`<section><h4>${esc(c.name)}</h4><p>${esc(c.text)}</p></section>`).join('')}</div><h3>Prática ativa</h3><ol class="cs-practice">${m.practice.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="success"><b>Critério de independência:</b> ${esc(m.independence)}</div><h3>Prove que entendeu</h3><p class="muted small">A AEDS não considera o módulo dominado só porque você leu. Escreva com suas palavras e faça transferência.</p><div class="grid g2"><label class="field"><span>Explique o mecanismo sem copiar a definição</span><textarea data-cs-note="explanation" data-cs-kind="module" data-cs-id="${esc(m.id)}" placeholder="Explique como se estivesse ensinando outra pessoa.">${esc(n.explanation||'')}</textarea></label><label class="field"><span>Transfira para um caso novo</span><textarea data-cs-note="transfer" data-cs-kind="module" data-cs-id="${esc(m.id)}" placeholder="Dê um exemplo, um caso de borda ou uma aplicação fora da AEDS.">${esc(n.transfer||'')}</textarea></label></div><div id="csModuleStatus" class="notice">Para concluir: pelo menos 40 caracteres de explicação e 30 de transferência.</div><button class="btn ${done?'btn-ok':'btn-primary'}" id="csCompleteModule" data-cs-id="${esc(m.id)}">${done?'Módulo concluído ✓':'Validar e concluir módulo'}</button></article></section>`}
function csTrailView(d){const p=csProgress();return `<div class="cs-trail-intro"><div><span class="eyebrow">DO ZERO AOS FUNDAMENTOS</span><h1>Ciência da Computação</h1><p>Não é uma lista de linguagens. É uma trilha para entender mecanismos, construir, medir e explicar.</p></div><div class="cs-progress-card"><span>Módulos concluídos</span><b>${p.modules}/${d.modules.length}</b><div class="mini-progress"><i style="width:${Math.round(p.modules/d.modules.length*100)}%"></i></div></div></div><div class="card cs-manifesto"><b>${esc(d.studyRule)}</b><p>O ciclo de domínio da trilha é:</p>${csCycleHtml()}</div><div class="course-layout cs-course-layout">${csModuleNav(d)}${csModuleArticle(d)}</div>`}
function csNotebook(kind,id,title,questions=[]){const n=csNote(kind,id);return `<div class="card cs-notebook"><div class="eyebrow">CADERNO DE EVIDÊNCIAS</div><h3>${esc(title)}</h3>${questions.length?`<div class="cs-decision-questions">${questions.map((q,i)=>`<p><b>${i+1}.</b> ${esc(q)}</p>`).join('')}</div>`:''}<div class="grid g2"><label class="field"><span>Hipótese / diagnóstico antes de ver a solução</span><textarea data-cs-note="hypothesis" data-cs-kind="${kind}" data-cs-id="${esc(id)}">${esc(n.hypothesis||'')}</textarea></label><label class="field"><span>Evidência observada</span><textarea data-cs-note="evidence" data-cs-kind="${kind}" data-cs-id="${esc(id)}">${esc(n.evidence||'')}</textarea></label><label class="field"><span>Explicação do mecanismo</span><textarea data-cs-note="explanation" data-cs-kind="${kind}" data-cs-id="${esc(id)}">${esc(n.explanation||'')}</textarea></label><label class="field"><span>Próximo teste</span><textarea data-cs-note="nextTest" data-cs-kind="${kind}" data-cs-id="${esc(id)}">${esc(n.nextTest||'')}</textarea></label></div><div class="tiny muted">As anotações ficam no seu progresso da AEDS e podem virar documentação de portfólio.</div></div>`}
function csCasesView(d){return `<div class="page-head"><div><h2>Estudos de caso aplicados</h2><div class="muted">Tente diagnosticar antes de abrir a análise original.</div></div><span class="pill">${d.cases.length} casos do arquivo</span></div><div class="cs-case-list">${d.cases.map((c,i)=>`<article class="card cs-case"><span class="eyebrow">CASO ${i+1}</span><h3>${esc(c.title)}</h3><p>${esc(c.scenario)}</p>${csNotebook('case',c.id,'Seu diagnóstico',c.questions)}<details class="cs-original-analysis"><summary>Revelar análise integral do autor</summary><pre>${esc(c.raw)}</pre></details><div class="success"><b>Lição:</b> ${esc(c.lesson)}</div></article>`).join('')}</div>`}
function csLabsView(d){return `<div class="page-head"><div><h2>Laboratórios</h2><div class="muted">Prever → executar → registrar → explicar → testar de novo.</div></div><span class="pill">Conhecimento executável</span></div>${d.labs.map((l,i)=>`<article class="card cs-lab"><span class="eyebrow">LABORATÓRIO ${i+1}</span><h3>${esc(l.title)}</h3><p>${esc(l.goal)}</p><h4>Procedimento</h4><ol>${l.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${csNotebook('lab',l.id,'Registro do laboratório')}<div class="success"><b>Critério de conclusão:</b> ${esc(l.finish)}</div><details><summary>Ver texto integral do laboratório no arquivo</summary><pre>${esc(l.raw)}</pre></details></article>`).join('')}`}
function csProjectsView(d){const p=csProgress();return `<div class="page-head"><div><h2>Projetos guiados</h2><div class="muted">Projetos servem para provar capacidade, não apenas preencher GitHub.</div></div><span class="pill">${p.projects}/${d.projects.length} concluídos</span></div><div class="cs-project-grid">${d.projects.map(pj=>{const n=csNote('project',pj.id),done=csIsDone('project',pj.id);return `<article class="card cs-project"><span class="project-number">${String(pj.n).padStart(2,'0')}</span><h3>${esc(pj.title)}</h3><p>${esc(pj.description)}</p><label class="field"><span>Que habilidade este projeto prova?</span><textarea data-cs-note="hypothesis" data-cs-kind="project" data-cs-id="${esc(pj.id)}">${esc(n.hypothesis||'')}</textarea></label><label class="field"><span>Evidência: código, testes, medição ou decisão documentada</span><textarea data-cs-note="evidence" data-cs-kind="project" data-cs-id="${esc(pj.id)}">${esc(n.evidence||'')}</textarea></label><button class="btn ${done?'btn-ok':'btn-soft'} cs-project-done" data-cs-id="${esc(pj.id)}">${done?'Projeto documentado ✓':'Marcar como documentado'}</button></article>`}).join('')}</div><div class="card" style="margin-top:14px"><h3>Checklist final do livro</h3><ul>${d.finalChecklist.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`}
function csGlossaryView(d){return `<div class="page-head"><div><h2>Glossário técnico</h2><div class="muted">Definições preservadas do arquivo original.</div></div><span class="pill">${d.glossary.length} termos</span></div><div class="searchbox cs-gloss-search"><span class="search-icon">${aedsIcon('search',18)}</span><input id="csGlossarySearch" placeholder="Buscar termo ou definição"></div><div class="cs-glossary" id="csGlossaryList">${d.glossary.map(g=>`<article class="card cs-gloss-item" data-cs-gloss="${esc((g.term+' '+g.definition).toLowerCase())}"><h4>${esc(g.term)}</h4><p>${esc(g.definition)}</p></article>`).join('')}</div>`}
function csBookView(d){return `<div class="page-head"><div><h2>Livro completo</h2><div class="muted">Texto integral preservado exatamente a partir do arquivo enviado.</div></div><span class="pill">${d.sourceLines} linhas</span></div><div class="warning"><b>Integridade da fonte:</b> alguns trechos recebidos começam no meio de uma sequência — por exemplo, aparecem exercícios 5–8 antes do capítulo 3. A AEDS não inventou as partes ausentes; preservou o material recebido e criou uma camada guiada separada.</div><div class="card cs-references"><h3>Referências recomendadas no livro</h3><ul>${d.references.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><details class="card cs-full-book"><summary><b>Abrir texto integral</b></summary><pre>${esc(d.sourceText)}</pre></details>`}
function csFoundationView(){const d=csBook();if(!d)return `<div class="danger">O arquivo cs-foundations.js não foi carregado.</div>`;ui.csTab=ui.csTab||'trilha';const body=ui.csTab==='casos'?csCasesView(d):ui.csTab==='laboratorio'?csLabsView(d):ui.csTab==='projetos'?csProjectsView(d):ui.csTab==='glossario'?csGlossaryView(d):ui.csTab==='livro'?csBookView(d):csTrailView(d);return `<div class="page-head cs-main-head"><div><span class="eyebrow">COMPUTAÇÃO</span><h1>${esc(d.title)}</h1><div class="muted">Conteúdo autoral integrado à AEDS · teoria, decisão, laboratório e portfólio.</div></div></div>${csModeSwitch()}${csTabs()}${body}`}

programView=function(){if(ui.programLang==='fundamentos_cs')return csFoundationView();const old=AEDS906_PROGRAM_VIEW();return `${csModeSwitch()}${old.replace('<h1>Programação</h1>','<h1>Linguagens e programação</h1>')}`}

runSearch=function(q){const base=AEDS906_RUN_SEARCH(q),d=csBook(),s=String(q||'').trim().toLowerCase();if(!d||s.length<2)return base;const extra=[];d.modules.forEach((m,i)=>{const hay=(m.title+' '+m.subtitle+' '+m.source+' '+m.concepts.map(c=>c.name+' '+c.text).join(' ')).toLowerCase();if(hay.includes(s))extra.push({type:'Ciência da Computação',title:m.title,sub:m.subtitle,action:{page:'program',lang:'fundamentos_cs',lesson:i}})});d.glossary.forEach(g=>{if((g.term+' '+g.definition).toLowerCase().includes(s))extra.push({type:'Glossário de Computação',title:g.term,sub:g.definition.slice(0,120),action:{page:'program',lang:'fundamentos_cs',lesson:0}})});return [...extra,...base].slice(0,35)}

wire=function(){AEDS906_WIRE();$$('[data-cs-mode]').forEach(b=>b.onclick=()=>{if(b.dataset.csMode==='fundamentos'){ui.programLang='fundamentos_cs';ui.programLesson=0;ui.csTab='trilha'}else{ui.programLang=ui.lastCodeLang&&PROGRAMMING[ui.lastCodeLang]&&!['fundamentos_cs'].includes(ui.lastCodeLang)?ui.lastCodeLang:'python'}render()});$$('[data-lang]').forEach(b=>{const old=b.onclick;b.onclick=()=>{ui.lastCodeLang=b.dataset.lang;old&&old()}});$$('[data-cs-tab]').forEach(b=>b.onclick=()=>{ui.csTab=b.dataset.csTab;render()});$$('[data-cs-module]').forEach(b=>b.onclick=()=>{ui.programLesson=Number(b.dataset.csModule)||0;ui.csTab='trilha';render()});$$('[data-cs-note]').forEach(el=>el.addEventListener('change',()=>{const n=csNote(el.dataset.csKind,el.dataset.csId);n[el.dataset.csNote]=el.value;n.updatedAt=new Date().toISOString();localSave()}));$('#csCompleteModule')?.addEventListener('click',e=>{const id=e.currentTarget.dataset.csId,n=csNote('module',id),st=$('#csModuleStatus');if((n.explanation||'').trim().length<40||(n.transfer||'').trim().length<30){st.className='warning';st.textContent='Ainda não: escreva uma explicação com pelo menos 40 caracteres e uma transferência com pelo menos 30.';return}csToggleDone('module',id);render()});$$('.cs-project-done').forEach(b=>b.onclick=()=>{const n=csNote('project',b.dataset.csId);if(!csIsDone('project',b.dataset.csId)&&(n.evidence||'').trim().length<30){alert('Antes de concluir, registre pelo menos uma evidência do que você construiu, testou ou mediu.');return}csToggleDone('project',b.dataset.csId);render()});$('#csGlossarySearch')?.addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();$$('.cs-gloss-item').forEach(x=>x.classList.toggle('hidden',q&&!String(x.dataset.csGloss||'').includes(q)))})}

