function markRastroCoverageGap(p){const uid=rastroUid(),m=rastroMap(uid),t=m[p.skillKey];if(t){const x=AEDS_RASTRO.setCoverage(t,'sem_contraprova_independente');x.spacedRetestQid=p.sourceQid;x.spacedRetestAt=Date.now()+2*AEDS_ENGINE.DAY;x.spacedRetestCue={...p,spacedRetest:true};m[p.skillKey]=x}state.rastroPending[uid]=null;ui.rastroLast={signal:p.signal,label:p.label,instruction:'Não existe contraprova independente suficiente no banco para esta habilidade. A AEDS não vai fingir domínio: manterá o caso aberto e rechecára o item após intervalo.',gate:{passed:false,level:'blocked'}};logUse('rastro_cobertura_insuficiente',p.skillKey)}
