function pickRastroQuestion(p,avoidIds=[]){return rastroQuestionPool(p,avoidIds,true)[0]||null}
function rastroCueHtml(){const c=ui.rastroCue;if(!c)return'';const m=c.studyMethod;return `<div class="rastro-cue"><div class="rastro-line"><span class="rastro-mark">R</span><div><b>Contraprova controlada</b><p>${esc(c.instruction||'Aplique a mesma habilidade em outra forma.')}</p>${m?`<p><b>Método de apoio: ${esc(m.title)}</b> — ${esc(m.instruction||'')}</p>`:''}</div></div><span class="tiny muted">Caso ${esc(c.caseId||'ativo')} · hipótese ${esc(c.label||'reconstrução')} · o método ajuda, mas não concede domínio por si só.</span></div>`}
function rastroFeedbackHtml(q){if(!ui.corrected)return'';const uid=rastroUid(),sum=AEDS_RASTRO.summary(rastroMap(uid)[rastroKey(q)]),last=ui.rastroLast;if(!sum&&!last)return'';const gate=last?.gate||sum?.gate,label=last?.label||sum?.label||'Rastro',instruction=last?.instruction||state.rastroPending?.[uid]?.instruction||'',passed=!!gate?.passed,recovered=sum?.caseStatus==='recovered';return `<div class="rastro-feedback ${passed?'rastro-stable':''}"><div class="rastro-line"><span class="rastro-mark">R</span><div><b>${passed?'Aprendizagem verificada':recovered?'Recuperado, ainda não verificado':'Rastro rigoroso: caso ainda aberto'}</b><p>${esc(passed?'A habilidade passou pelo protocolo máximo: volume, diversidade, transferência, retenção longa e sequência final verificadas.':recovered?'A contraprova independente foi vencida. A AEDS ainda exige uma nova recuperação após intervalo antes de considerar o caso encerrado.':instruction||`A hipótese atual é ${label.toLowerCase()}.`)}</p></div></div>${!passed?`<small>Hipótese: ${esc(label)}. Um acerto isolado não encerra o caso. ${sum?.coverageBlocked?'O banco ainda não possui contraprova independente suficiente para esta habilidade.':''}</small>`:''}</div>`}
