function loadRastroPending(){const uid=rastroUid(),p=state.rastroPending?.[uid];if(!p)return false;if(p.subject!==ui.subject||Number(p.grade)!==Number(ui.grade)||p.area!==ui.area)return false;const q=pickRastroQuestion(p);if(!q){deferRastroProbe(p);return false}const t=rastroMap(uid)[p.skillKey];if(t)rastroMap(uid)[p.skillKey]=AEDS_RASTRO.clearCoverage(t);state.rastroPending[uid]=null;ui.rastroCue=p;ui.question=q;ui.mathSkill=q.skill||ui.mathSkill;ui.selected=null;ui.cdf=null;ui.cid=null;ui.corrected=false;ui.hint=false;ui.started=Date.now();state.sessionDrafts[uid]=null;saveSessionDraft();localSave();render();return true}
