const AEDS908_setCID=setCID;
setCID=async function(v){await AEDS908_setCID(v);if(ui.question){rebuildRastroSkill(ui.question,{setPending:true});localSave();render()}}
const AEDS908_nextTrainingQuestion=nextTrainingQuestion;
