const AEDS908_advanceSmartStudy=advanceSmartStudy;
advanceSmartStudy=function(){const uid=rastroUid(),pending=state.rastroPending?.[uid];if(pending)injectRastroIntoSession(pending);const ss=ui.studySession,next=ss?.items?.[ss.index+1];if(next?.rastro)ui.rastroCue=next.cue||null;else ui.rastroCue=null;return AEDS908_advanceSmartStudy()}

const AEDS908_smartPlan=smartPlan;
smartPlan=function(mode='study',limit=7){const plan=AEDS908_smartPlan(mode,limit),uid=rastroUid(),now=Date.now();const due=[];for(const [k,t0] of Object.entries(rastroMap(uid))){const t=AEDS_RASTRO.normalize(t0);if(t.spacedRetestQid&&t.spacedRetestAt&&t.spacedRetestAt<=now){const q=qById(t.spacedRetestQid);if(q&&!plan.some(z=>z.q.id===q.id))due.push({k,t,q})}}if(due.length){const x=due[0],parts=x.k.split('|'),saved=x.t.spacedRetestCue||{},p={...saved,sourceQid:saved.sourceQid||x.q.id,skillKey:x.k,subject:parts[0],grade:Number(parts[1]),area:parts[2],skill:parts.slice(3).join('|'),signal:saved.signal||'retencao',label:saved.label||'Retenção',route:saved.route||{preTeach:false},instruction:'Rechecagem espaçada: tente resolver novamente sem consultar a solução anterior.',spacedRetest:true};plan.unshift({q:x.q,type:'rastro-retention',reason:'Rastro · rechecagem espaçada do item que antes falhou',strategy:'attempt_first',rastro:true,cue:p});if(plan.length>limit)plan.pop();x.t.spacedRetestAt=0;x.t.waitingForSpacing=false;return plan}
  const traces=Object.entries(rastroMap(uid)).map(([k,t])=>({k,s:AEDS_RASTRO.summary(t)})).filter(x=>x.s&&!x.s.gate?.passed&&!x.s.coverageBlocked&&x.s.caseStatus!=='recovered'&&x.s.score>=.45).sort((a,b)=>b.s.score-a.s.score);for(const x of traces.slice(0,3)){const parts=x.k.split('|'),subject=parts[0],grade=Number(parts[1]),area=parts[2],skill=parts.slice(3).join('|'),fake={difficulty:'médio'},route=AEDS_RASTRO.route(x.s.key,fake,{failures:x.s.caseFailures||0,escalation:x.s.caseFailures||0});if(!route)continue;const p=rastroAttachMethod({sourceQid:null,sourceFamily:null,sourcePattern:null,skillKey:x.k,subject,grade,area,skill,signal:x.s.key,label:x.s.label,route,instruction:route.instruction}),q=pickRastroQuestion(p,plan.map(z=>z.q.id));if(q&&!plan.some(z=>z.q.id===q.id)){plan.unshift({q,type:'rastro',reason:`Rastro · ${x.s.label}: ${route.instruction}`,strategy:route.preTeach?'explain_first':'attempt_first',rastro:true,cue:p});if(plan.length>limit)plan.pop();break}}return plan}
const AEDS908_startSmartStudy=startSmartStudy;
startSmartStudy=function(mode='study'){const plan=smartPlan(mode,7);if(!plan.length)return alert('Não há questões realmente inéditas suficientes para montar uma sessão agora. A AEDS prefere parar a repetir modelos antigos.');ui.studySession={mode,items:plan.map(x=>({qid:x.q.id,type:x.type,reason:x.reason,strategy:x.strategy,result:null,rastro:!!x.rastro,cue:x.cue||null})),index:0,startedAt:Date.now(),finished:false};const first=ui.studySession.items[0],q=qById(first.qid);ui.page='train';ui.subject=q.subject;ui.grade=Number(q.grade);ui.area=q.area;ui.mathSkill=q.skill||'auto';ui.question=q;ui.preTeach=first.strategy==='explain_first';ui.rastroCue=first.rastro?first.cue:null;ui.selected=null;ui.cdf=null;ui.cid=null;ui.corrected=false;ui.hint=false;ui.started=Date.now();logUse('sessao_inteligente_iniciada',plan.map(x=>x.type).join(','));render()}

const AEDS908_finishExam=finishExam;
finishExam=function(){const before=stats().history.length;AEDS908_finishExam();const rows=stats().history.slice(before);for(const rec of rows){const q=qById(rec.qid);if(q)applyRastroRecord(q,rec,{setPending:false})}localSave()}
const AEDS908_startExamReview=startExamReview;
startExamReview=function(){const uid=rastroUid(),queue=[...(state.reviewQueue[uid]||[])];queue.sort((a,b)=>{const qa=qById(a.qid),qb=qById(b.qid),sa=qa?AEDS_RASTRO.summary(rastroMap(uid)[rastroKey(qa)])?.score||0:0,sb=qb?(AEDS_RASTRO.summary(rastroMap(uid)[rastroKey(qb)])?.score||0):0;return sb-sa});ui.examReview={queue,index:0,showLesson:true};ui.page='review';render()}

