const AEDS909_WIRE=wire;
wire=function(){AEDS909_WIRE();$$('.clearRastroManual').forEach(b=>b.onclick=()=>clearRastroManualReview(b.dataset.rastroUid,b.dataset.rastroKey,b.dataset.rastroCase))}

// ---------- AEDS 9.0.11: conquistas por evidência ----------
function achievementUid(){return targetStudent()?.id||me()?.id||null}
function achievementContext(uid=achievementUid()){
  const s=stats(uid),r=state.rastro?.[uid]||{};
  const independentSkills=Object.keys(s.skill||{}).filter(k=>stageForSkillKey(k,uid).level===4).length;
  return {stats:s,rastro:r,rastroApi:window.AEDS_RASTRO,methodsApi:window.AEDS_METHODS,independentSkills};
}
function refreshAchievements(showToast=false){
  const uid=achievementUid();if(!uid||!window.AEDS_ACHIEVEMENTS)return [];
  state.achievements=state.achievements||{};state.achievements[uid]=state.achievements[uid]||{};
  const result=AEDS_ACHIEVEMENTS.unlock(state.achievements[uid],achievementContext(uid));
  if(!result.unlocked.length)return [];
  state.achievements[uid]=result.earned;localSave();
  if(showToast)setTimeout(()=>showAchievementToast(result.unlocked),0);
  return result.unlocked;
}
function showAchievementToast(items=[]){
  if(!items.length)return;document.querySelector('.achievement-toast')?.remove();
  const a=items[items.length-1],el=document.createElement('div');el.className='achievement-toast';
  el.setAttribute('role','status');el.innerHTML=`<span class="achievement-seal">A</span><div><small>Nova conquista</small><b>${esc(a.title)}</b><p>${esc(a.detail||a.desc)}</p>${items.length>1?`<em>+ ${items.length-1} outra(s) conquista(s)</em>`:''}</div>`;
  document.body.appendChild(el);setTimeout(()=>el.classList.add('show'),30);setTimeout(()=>{el.classList.remove('show');setTimeout(()=>el.remove(),250)},5200);
}
function achievementProgressHtml(a){const v=Math.max(0,Math.min(100,Math.round((a.progress||0)*100)));return `<div class="achievement-progress"><span style="width:${v}%"></span></div>`}
function achievementsHtml(){
  const uid=achievementUid();if(!uid||!window.AEDS_ACHIEVEMENTS)return'';refreshAchievements(false);
  const earned=state.achievements?.[uid]||{},all=AEDS_ACHIEVEMENTS.evaluate(achievementContext(uid));
  const got=all.filter(a=>earned[a.id]).sort((a,b)=>String(earned[b.id]?.unlockedAt||'').localeCompare(String(earned[a.id]?.unlockedAt||'')));
  const next=all.filter(a=>!earned[a.id]).sort((a,b)=>(b.progress||0)-(a.progress||0)).slice(0,6);
  const method=AEDS_ACHIEVEMENTS.strategyEvidence(stats(uid).history||[]),mp=window.AEDS_METHODS?.profile(stats(uid).history||[]);
  const methodText=mp?.validated&&mp.best?`Entre os métodos testados, ${mp.best.method.title} está produzindo a melhor evidência até agora (${Math.round(mp.best.score*100)}% ponderado em ${mp.best.n} usos). A AEDS continuará tentando refutar essa conclusão.`:method.winner==='attempt_first'?'Os dados indicam que você rende melhor tentando antes da explicação.':method.winner==='explain_first'?'Os dados indicam que você rende melhor vendo uma explicação antes da tentativa.':method.winner==='flexible'?'As duas estratégias estão funcionando de forma muito parecida para você.':'A AEDS ainda está testando métodos diferentes; nenhuma preferência foi comprovada.';
  return `<section class="card achievements-card"><div class="page-head achievements-head"><div><span class="eyebrow">CONQUISTAS</span><h3>Provas do que você construiu</h3><p class="muted">Sem prêmio por login ou clique. Aqui entram marcos, transferência, retenção e autonomia comprovadas.</p></div><div class="achievement-total"><b>${got.length}</b><span>conquistadas</span></div></div>
  <div class="achievement-method"><span class="achievement-seal">M</span><div><b>Descoberta do método de estudo</b><p>${esc(methodText)}</p><small>Tentativa primeiro: ${method.attempt.n} evidências · Explicação primeiro: ${method.explain.n} evidências.</small></div></div>
  ${got.length?`<div class="achievement-grid">${got.slice(0,8).map(a=>`<article class="achievement earned"><span class="achievement-seal">${esc(a.group[0].toUpperCase())}</span><div><b>${esc(a.title)}</b><p>${esc(a.desc)}</p><small>${esc(earned[a.id]?.detail||a.detail||'Conquistada')}</small></div></article>`).join('')}</div>`:'<div class="notice">As primeiras conquistas aparecem quando houver evidência real de aprendizagem.</div>'}
  ${next.length?`<details class="achievement-next"><summary>Próximas conquistas</summary><div class="achievement-grid">${next.map(a=>`<article class="achievement locked"><div><b>${esc(a.title)}</b><p>${esc(a.desc)}</p><small>${esc(a.detail)}</small>${achievementProgressHtml(a)}</div></article>`).join('')}</div></details>`:''}
  <details class="achievement-next"><summary>Ver catálogo completo (${all.length})</summary><div class="achievement-catalog">${all.map(a=>`<div class="achievement-catalog-row ${earned[a.id]?'done':''}"><span>${earned[a.id]?'Conquistada':'Em progresso'}</span><b>${esc(a.title)}</b><small>${esc(earned[a.id]?.detail||a.detail||a.desc)}</small></div>`).join('')}</div></details></section>`;
}
const AEDS909_PERFORMANCE_VIEW=performanceView;
performanceView=function(){const out=AEDS909_PERFORMANCE_VIEW();return out.replace('<div class="grid g2" style="margin-top:14px">',achievementsHtml()+'<div class="grid g2" style="margin-top:14px">')}
const AEDS909_CONFIRM_ACHIEVEMENTS=confirmQuestion;
confirmQuestion=async function(){const before=stats().questions;await AEDS909_CONFIRM_ACHIEVEMENTS();if(stats().questions>before)refreshAchievements(true)}

