if(location.protocol!=='file:'&&'serviceWorker' in navigator){navigator.serviceWorker.register('sw.js').catch(()=>{})}
decodeData().catch(e=>{APP.innerHTML=`<div class="login"><div class="card"><h2>A AEDS não conseguiu abrir.</h2><p>${esc(e.message)}</p><p>Mantenha a estrutura completa da AEDS ${esc(window.AEDS_APP?.version||'9.0.13')}, incluindo <b>content-core.js</b>, <b>content-loader.js</b> e a pasta <b>data/questions</b>.</p></div></div>`});
